        Question(10500, "Quel est l'animal terrestre le plus rapide?", listOf("Le lion", "Le guépard", "L'antilope", "Le lièvre"), 1, "Nature", Difficulty.EASY, explanation = "Le guépard peut atteindre 110 km/h en pointe sur de courtes distances, grâce à sa colonne vertébrale flexible et ses griffes non rétractiles qui lui offrent une adhérence maximale."),
