        Question(10502, "Quel est le plus grand océan du monde?", listOf("Océan Atlantique", "Océan Indien", "Océan Pacifique", "Océan Arctique"), 2, "Nature", Difficulty.EASY, explanation = "L'océan Pacifique couvre environ 165 millions de kilomètres carrés, soit plus du tiers de la surface terrestre, ce qui en fait le plus vaste océan du monde."),
        Question(10503, "Quel arbre produit les glands?", listOf("Le bouleau", "Le chêne", "Le sapin", "Le peuplier"), 1, "Nature", Difficulty.EASY, explanation = "Le gland est le fruit du chêne, un arbre de la famille des Fagacées, reconnaissable à sa cupule écailleuse."),
        Question(10504, "Combien de chambres a le cœur d'un poisson?", listOf("2", "3", "4", "6"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le cœur des poissons est composé de deux chambres principales : une oreillette et un ventricule, ce qui permet une circulation sanguine simple et efficace adaptée à leur environnement aquatique."),
        Question(10505, "Quel est le plus haut sommet du monde?", listOf("K2", "Mont-Blanc", "Everest", "Mont Kilimandjaro"), 2, "Nature", Difficulty.EASY, explanation = "L'Everest, culminant à 8 848 mètres, est le point le plus élevé de la croûte terrestre, situé dans l'Himalaya à la frontière du Népal et du Tibet."),
