        Question(10508, "Quel mammifère pond des œufs?", listOf("Le koala", "L'ornithorynque", "Le kangourou", "Le wombat"), 1, "Nature", Difficulty.MEDIUM, explanation = "L'ornithorynque est l'un des rares mammifères monotrèmes, un groupe qui pond des œufs au lieu de donner naissance à des petits vivants."),
        Question(10509, "Quelle est la plus profonde fosse océanique?", listOf("Fosse des Mariannes", "Fosse de Tonga", "Fosse de Kuril", "Fosse de Mindanao"), 0, "Nature", Difficulty.HARD, explanation = "La fosse des Mariannes, située dans l'océan Pacifique, atteint environ 11 034 mètres de profondeur à son point le plus bas, appelé le Challenger Deep."),
