        Question(10512, "Quel est le plus grand animal du monde?", listOf("L'éléphant", "L'hippopotame", "La baleine bleue", "Le giraffe"), 2, "Nature", Difficulty.EASY, explanation = "La baleine bleue peut atteindre jusqu'à 30 mètres de long et peser plus de 170 tonnes, ce qui en fait le plus grand animal jamais connu sur Terre."),
        Question(10513, "Quel est le plus long serpent du monde?", listOf("Le boa constricteur", "L'anaconda", "Le python réticulé", "Le cobra royal"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le python réticulé peut atteindre plus de 10 mètres de long, ce qui en fait le serpent le plus long, dépassant l'anaconda en longueur mais pas en poids."),
        Question(10514, "Combien d'espèces de papillons existe-t-il environ?", listOf("5 000", "17 500", "50 000", "100 000"), 1, "Nature", Difficulty.HARD, explanation = "La France métropolitaine compte environ 5 000 espèces de papillons de jour et de nuit, mais à l'échelle mondiale, on en dénombre environ 17 500 espèces de papillons de jour."),
        Question(10515, "Quel est le plus grand prédateur des mers?", listOf("La murène", "Le barracuda", "Le grand requin blanc", "Le piranha"), 2, "Nature", Difficulty.EASY, explanation = "Le grand requin blanc peut mesurer jusqu'à 6 mètres de long et peser plus de 2 tonnes, ce qui en fait le plus grand poisson prédateur des océans."),
        Question(10516, "Combien de dents a un éléphant?", listOf("4", "8", "16", "32"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les éléphants possèdent quatre molaires en fonctionnement à la fois, deux en haut et deux en bas, qui sont remplacées jusqu'à six fois au cours de leur vie, ce qui donne un total de 8 dents visibles à un moment donné."),
        Question(10517, "Quel animal a le plus long cou?", listOf("L'autruche", "Le chameau", "La girafe", "L'émeu"), 2, "Nature", Difficulty.EASY, explanation = "La girafe possède le plus long cou de tous les animaux, mesurant jusqu'à 2,4 mètres, ce qui lui permet d'atteindre les feuilles hautes des arbres."),
        Question(10518, "Quel poisson peut sortir de l'eau?", listOf("La carpe", "Le silure", "Le poisson-chat", "Le protoptère"), 3, "Nature", Difficulty.HARD, explanation = "Le protoptère, aussi appelé poisson-poumon, possède des poumons lui permettant de respirer hors de l'eau et de survivre plusieurs mois dans la boue pendant la saison sèche."),
        Question(10519, "Combien de côtes a un humain?", listOf("10", "12", "24", "30"), 1, "Nature", Difficulty.MEDIUM, explanation = "L'humain possède 12 paires de côtes, soit 24 côtes au total, qui forment la cage thoracique."),
        Question(10520, "Quel est le plus petit oiseau du monde?", listOf("Le roitelet", "Le colibri", "Le moineau", "Le rouge-gorge"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le colibri, et plus précisément le colibri d'Elena ou colibri-abeille, mesure environ 6 centimètres et pèse moins de 2 grammes, ce qui en fait le plus petit oiseau du monde."),
        Question(10521, "Combien de continents y a-t-il?", listOf("5", "6", "7", "8"), 2, "Nature", Difficulty.EASY, explanation = "Le modèle des sept continents (Afrique, Amérique du Nord, Amérique du Sud, Antarctique, Asie, Europe, Océanie) est le plus enseigné dans les pays francophones."),
        Question(10522, "Quel arbre est le plus haut du monde?", listOf("Le sapin de Douglas", "L'épicéa de Sitka", "Le séquoia géant", "L'eucalyptus"), 2, "Nature", Difficulty.HARD, explanation = "Le séquoia géant, notamment le spécimen nommé Hyperion, atteint plus de 115 mètres de hauteur, ce qui en fait l'arbre le plus haut du monde. Il pousse dans les forêts de la côte ouest des États-Unis."),
        Question(10523, "Combien de secondes a le cycle de vie d'un moustique?", listOf("Quelques jours", "2-3 semaines", "2-3 mois", "6 mois"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le cycle de vie du moustique, de l'œuf à l'adulte, dure généralement de 2 à 3 semaines, selon les conditions de température et d'humidité."),
        Question(10524, "Quel est le plus long fleuve du monde?", listOf("Le Nil", "L'Amazone", "Le Yangzi", "le Mississippi"), 0, "Nature", Difficulty.EASY, explanation = "Le Nil est traditionnellement considéré comme le plus long fleuve du monde, avec une longueur d'environ 6 650 kilomètres, traversant l'Afrique de l'Est jusqu'à la Méditerranée."),
        Question(10525, "Combien de sortes de plantes à fleurs existe-t-il?", listOf("100 000", "250 000", "500 000", "1 million"), 1, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ 250 000 espèces de plantes à fleurs dans le monde, ce qui en fait le groupe de plantes le plus diversifié sur Terre."),
        Question(10526, "Quel animal peut vivre le plus longtemps?", listOf("L'éléphant", "Le perroquet", "La tortue géante", "Le requin"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les tortues géantes, notamment celles des Galápagos, peuvent dépasser 150 ans, ce qui en fait les vertébrés terrestres les plus longévifs."),
        Question(10527, "Quel est le plus rapide des oiseaux?", listOf("L'aigle", "Le faucon pèlerin", "L'hirondelle", "Le martin-pêcheur"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le faucon pèlerin est l'oiseau le plus rapide du monde, atteignant plus de 300 km/h en piqué lors de ses chasses."),
        Question(10528, "Combien de cellules a le corps humain environ?", listOf("10 milliards", "37 billions", "100 billions", "1 trillion"), 1, "Nature", Difficulty.HARD, explanation = "Le corps humain adulte est composé d'environ 37 billions de cellules, une estimation basée sur des études scientifiques récentes. Ce nombre varie selon l'âge, la taille et le poids de l'individu."),
        Question(10529, "Quel est le plus grand mammifère terrestre?", listOf("L'hippopotame", "L'éléphant", "La girafe", "Le rhinocéros"), 1, "Nature", Difficulty.EASY, explanation = "L'éléphant d'Afrique est le plus grand mammifère terrestre, pouvant peser jusqu'à 6 tonnes et mesurer plus de 3 mètres au garrot."),
        Question(10530, "Quel animal peut dormir en restant debout?", listOf("Le cheval", "La vache", "L'âne", "Le chameau"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les chevaux possèdent un système de verrouillage des pattes appelé \"appareil de soutien\" qui leur permet de dormir debout sans tomber, une adaptation héritée de leurs ancêtres sauvages pour fuir rapidement les prédateurs."),
        Question(10531, "Combien de branches a un arbre généalogique?", listOf("2", "3", "4", "Illimité"), 3, "Nature", Difficulty.EASY, explanation = "Un arbre généalogique peut représenter un nombre infini de générations et de ramifications, car il n'y a pas de limite au nombre d'ancêtres ou de descendants que l'on peut inclure."),
        Question(10532, "Quel est le plus venimeux des serpents?", listOf("Le cobra royal", "Le serpent taïpan", "L'aspic", "La vipère"), 1, "Nature", Difficulty.HARD, explanation = "Le serpent taïpan, originaire d'Australie, possède le venin le plus toxique de tous les serpents, capable de tuer un humain en moins d'une heure."),
