        Question(10534, "Quel est le plus grand insecte du monde?", listOf("La cicindèle", "Le scarabée Hercule", "Le bousier", "La sauterelle géante"), 1, "Nature", Difficulty.HARD, explanation = "Le scarabée Hercule, originaire d'Amérique centrale et du Sud, peut mesurer jusqu'à 17 cm de long, cornes comprises, ce qui en fait l'insecte le plus long du monde."),
        Question(10535, "Quel oiseau pond les plus grands œufs?", listOf("L'autruche", "L'émeu", "Le casoar", "L'albatros"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'autruche est le plus grand oiseau vivant, et ses œufs peuvent peser jusqu'à 1,5 kg, ce qui en fait les plus gros du monde aviaire."),
        Question(10536, "Combien de sortes de fleurs existe-t-il environ?", listOf("100 000", "300 000", "400 000", "500 000"), 1, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ 300 000 espèces de plantes à fleurs (angiospermes) dans le monde, un chiffre qui continue d'évoluer avec les découvertes botaniques."),
        Question(10537, "Quel animal a le plus mauvais odorat?", listOf("L'humain", "Le dauphin", "Le hibou", "L'anguille"), 0, "Nature", Difficulty.MEDIUM, explanation = "Parmi les mammifères, l'humain possède le moins de récepteurs olfactifs fonctionnels, ce qui le place en bas de l'échelle de l'odorat."),
        Question(10538, "Quel est le plus profond lac du monde?", listOf("Le lac Baïkal", "Le lac Tanganyika", "Le lac Malawi", "Le lac Supérieur"), 0, "Nature", Difficulty.HARD, explanation = "Le lac Baïkal, situé en Sibérie, atteint une profondeur maximale de 1 642 mètres, ce qui en fait le lac le plus profond de la planète."),
        Question(10539, "Combien de sortes de requins existe-t-il?", listOf("100", "400", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "On recense environ 500 espèces de requins dans le monde, allant du petit requin-lanterne nain au grand requin blanc."),
        Question(10540, "Quel animal peut retenir son souffle le plus longtemps?", listOf("Le dauphin", "La baleine", "L'otarie", "Le castor"), 1, "Nature", Difficulty.HARD, explanation = "Les baleines, comme le cachalot, peuvent rester sous l'eau jusqu'à 90 minutes grâce à leur capacité à stocker l'oxygène dans leurs muscles et leur sang."),
        Question(10541, "Quel est le plus ancien arbre vivant?", listOf("Le pin des Bristlecone", "Le séquoia géant", "L'épicéa de Sitka", "L'if d'Europe"), 0, "Nature", Difficulty.HARD, explanation = "Le pin Bristlecone, notamment le spécimen surnommé Mathusalem, est considéré comme l'arbre non clonal le plus âgé, avec un âge estimé à près de 5 000 ans."),
        Question(10542, "Combien de dents a un croc?", listOf("2", "4", "6", "8"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le terme \"croc\" désigne généralement une canine pointue, et on parle souvent d'une paire de crocs chez un animal, comme le serpent ou le chien."),
