        Question(10544, "Combien de temps vit un papillon?", listOf("1-2 jours", "1-2 semaines", "1-2 mois", "6 mois"), 1, "Nature", Difficulty.MEDIUM, explanation = "La plupart des papillons adultes vivent seulement une à deux semaines, car leur cycle de vie est court après la métamorphose, consacré à la reproduction."),
