        Question(10546, "Combien de sortes de méduses existe-t-il?", listOf("50", "200", "500", "2000"), 3, "Nature", Difficulty.HARD, explanation = "On recense environ 2000 espèces de méduses dans les océans du monde, allant des formes côtières aux espèces des grandes profondeurs."),
        Question(10547, "Quel animal peut changer de couleur le plus rapidement?", listOf("La grenouille", "Le caméléon", "La seiche", "Le poisson-scorpion"), 2, "Nature", Difficulty.MEDIUM, explanation = "La seiche possède des cellules cutanées appelées chromatophores qu'elle contracte ou dilate en une fraction de seconde pour modifier son apparence."),
        Question(10548, "Quel est le plus grand pic-vert du monde?", listOf("Le pic noir", "Le pic à bec ivoire", "Le grand pic", "Le pic vert"), 1, "Nature", Difficulty.HARD, explanation = "Le pic à bec ivoire, mesurant jusqu'à 50 cm, est le plus grand pic-vert connu, mais il est probablement éteint, sa dernière observation confirmée datant des années 1940 aux États-Unis."),
        Question(10549, "Combien de sortes de fourmis existe-t-il?", listOf("100", "1000", "13 000", "50 000"), 2, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ 13 000 espèces de fourmis décrites dans le monde, bien que le nombre réel pourrait atteindre 20 000."),
        Question(10550, "Quel animal a le cœur le plus gros?", listOf("L'éléphant", "Le giraffe", "La baleine", "L'hippopotame"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le cœur de la baleine bleue peut peser jusqu'à 600 kg, ce qui en fait le plus gros de tous les animaux."),
        Question(10551, "Quel arbre produit le latex?", listOf("Le hévéa", "L'hévéa", "Le pin", "Le palmier"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le latex est un liquide visqueux récolté en incisant l'écorce de l'hévéa, un arbre originaire d'Amazonie, principalement utilisé pour fabriquer le caoutchouc naturel."),
        Question(10552, "Combien de dents a un requin blanc?", listOf("20", "40", "80", "150"), 3, "Nature", Difficulty.HARD, explanation = "Le grand requin blanc possède environ 300 dents disposées en plusieurs rangées, mais seulement une cinquantaine sont visibles à la fois, ce qui explique le chiffre de 150 souvent cité comme moyenne."),
        Question(10553, "Quel est le plus haut waterfall du monde?", listOf("Iguazu", "Victoria", "Niagara", "Angel"), 3, "Nature", Difficulty.MEDIUM, explanation = "Les chutes Angel, au Venezuela, mesurent 979 mètres de hauteur, ce qui en fait la plus haute cascade du monde. Elles sont nommées d'après l'aviateur Jimmy Angel."),
        Question(10554, "Quel animal peut voir dans l'infrarouge?", listOf("Le chat", "Le serpent à sonnettes", "L'aigle", "Le requin"), 1, "Nature", Difficulty.HARD, explanation = "Le serpent à sonnettes possède des fossettes thermosensibles entre les yeux et les narines qui détectent la chaleur émise par ses proies, lui permettant ainsi de \"voir\" dans l'infrarouge."),
        Question(10555, "Combien de sortes de coraux existe-t-il?", listOf("100", "800", "2500", "10 000"), 2, "Nature", Difficulty.HARD, explanation = "Les scientifiques ont recensé environ 2 500 espèces de coraux durs, qui construisent les récifs coralliens, principalement dans les eaux tropicales."),
        Question(10556, "Quel est le plus grand lézard du monde?", listOf("Le dragon de Komodo", "Le varan du Nil", "L'iguane vert", "Le lézard à cornes"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le dragon de Komodo, endémique d'Indonésie, peut atteindre 3 mètres de long et peser jusqu'à 90 kg, ce qui en fait le plus grand lézard vivant."),
        Question(10557, "Combien de sortes de chauves-souris existe-t-il?", listOf("100", "500", "1300", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Avec environ 1300 espèces recensées, les chauves-souris représentent le deuxième ordre de mammifères le plus diversifié après les rongeurs."),
        Question(10558, "Quel animal a la plus longue durée de gestation?", listOf("La baleine", "L'éléphant", "La girafe", "L'hippopotame"), 1, "Nature", Difficulty.HARD, explanation = "La gestation de l'éléphant dure environ 22 mois, soit près de deux ans, ce qui est la plus longue période de gestation chez tous les mammifères terrestres."),
