        Question(10560, "Combien de sortes de tortues existe-t-il?", listOf("100", "300", "500", "1000"), 1, "Nature", Difficulty.HARD, explanation = "Il existe environ 300 espèces de tortues dans le monde, réparties entre tortues terrestres, aquatiques et marines."),
