        Question(10562, "Quel est le plus long insecte du monde?", listOf("La sauterelle géante", "Le bâton du Borneo", "L'insecte-feuille", "La libellule géante"), 1, "Nature", Difficulty.HARD, explanation = "Le Phasme bâton du Bornéo (Phobaeticus chani) détient le record de l'insecte le plus long, avec une femelle mesurant 56,7 centimètres, pattes comprises. Il vit dans les forêts tropicales de Bornéo."),
        Question(10563, "Combien de sortes d'amphibiens existe-t-il?", listOf("500", "2000", "8000", "15 000"), 2, "Nature", Difficulty.HARD, explanation = "Les scientifiques ont recensé environ 8000 espèces d'amphibiens dans le monde, incluant grenouilles, crapauds, salamandres et tritons."),
        Question(10564, "Quel animal peut produire du venin mais n'est pas un reptile?", listOf("La chauve-souris", "L'ornithorynque", "Le hérisson", "L'ours"), 1, "Nature", Difficulty.HARD, explanation = "Le mâle de l'ornithorynque possède un aiguillon sur sa patte arrière qui injecte un venin, ce qui en fait un mammifère venimeux."),
        Question(10565, "Quel est le plus grand crustacé du monde?", listOf("Le crabe royal des neiges", "Le crabe dormeur", "Le crabe géant du Japon", "La langouste"), 2, "Nature", Difficulty.HARD, explanation = "Le crabe géant du Japon, aussi appelé crabe-araignée, peut atteindre une envergure de pattes de près de 4 mètres, ce qui en fait le plus grand crustacé connu."),
        Question(10566, "Combien de sortes de plancton existe-t-il?", listOf("100", "1000", "10 000", "100 000"), 2, "Nature", Difficulty.HARD, explanation = "Le plancton regroupe une diversité immense d'organismes aquatiques microscopiques, avec environ 10 000 espèces recensées, incluant phytoplancton et zooplancton."),
        Question(10567, "Quel animal peut émettre une lumière?", listOf("La luciole", "La méduse", "Le poisson des abysses", "Le ver luisant"), 1, "Nature", Difficulty.MEDIUM, explanation = "Certaines méduses possèdent des cellules bioluminescentes qui produisent une lumière bleue ou verte, utilisée pour attirer des proies ou se défendre."),
        Question(10568, "Quel est le plus grand marsupial du monde?", listOf("Le koala", "Le kangourou roux", "Le wombat", "le diable de Tasmanie"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le kangourou roux, mâle, peut mesurer jusqu'à 2 mètres de haut et peser 90 kg, ce qui en fait le plus grand marsupial vivant."),
        Question(10569, "Combien de sortes de grenouilles existe-t-il?", listOf("1000", "3000", "5000", "7000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 5 000 espèces de grenouilles connues dans le monde, ce qui en fait l'un des groupes d'amphibiens les plus diversifiés."),
        Question(10570, "Quel animal peut marcher sur l'eau?", listOf("L'insecte aquatique", "Le basilic", "La libellule", "Le patin"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le basilic, aussi appelé lézard Jésus-Christ, peut courir sur l'eau grâce à ses pattes arrière rapides et à la tension superficielle de l'eau."),
        Question(10571, "Quel est le plus grand pingouin du monde?", listOf("Le pingouin d'Adélie", "Le pingouin empereur", "le pingouin royal", "Le pingouin de Gentoo"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le pingouin empereur peut atteindre 1,20 mètre et peser jusqu'à 40 kilos, ce qui en fait la plus grande espèce de pingouin."),
        Question(10572, "Combien de sortes d'algues existe-t-il?", listOf("500", "2000", "30 000", "100 000"), 2, "Nature", Difficulty.HARD, explanation = "Les scientifiques estiment qu'il existe environ 30 000 espèces d'algues dans le monde, allant des microalgues unicellulaires aux grandes algues marines."),
        Question(10573, "Quel animal peut vivre dans le désert sans boire d'eau?", listOf("Le chameau", "Le scorpion", "Le coyote", "Le renard"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le scorpion tire l'eau dont il a besoin de ses proies, comme les insectes, et possède un métabolisme très économe en eau."),
        Question(10574, "Quel est le plus grand poisson d'eau douce du monde?", listOf("Le sandre", "L'esturgeon blanc", "Le silure géant", "Le barbeau"), 2, "Nature", Difficulty.HARD, explanation = "Le silure géant du Mékong peut atteindre près de 3 mètres de long et peser jusqu'à 300 kg, ce qui en fait le plus grand poisson d'eau douce connu."),
        Question(10575, "Combien de sortes de libellules existe-t-il?", listOf("500", "2000", "5000", "10 000"), 2, "Nature", Difficulty.HARD, explanation = "Le terme \"libellule\" désigne environ 5000 espèces réparties dans l'ordre des odonates, incluant les libellules proprement dites et les demoiselles."),
        Question(10576, "Quel animal peut tomber de la plus haute altitude sans se blesser?", listOf("La grue", "La chauve-souris", "le chat", "Le pigeon"), 2, "Nature", Difficulty.HARD, explanation = "Les chats possèdent un réflexe de redressement qui leur permet de se retourner en chute libre et d'atterrir sur leurs pattes, ce qui réduit l'impact."),
        Question(10577, "Quel est le plus grand mollusque du monde?", listOf("le calmar géant", "la seiche géante", "la moule géante", "l'huître géante"), 0, "Nature", Difficulty.HARD, explanation = "Le calmar géant (Architeuthis dux) peut atteindre jusqu'à 18 mètres de long, ce qui en fait le plus grand mollusque connu, dépassant tous les autres céphalopodes et mollusques marins."),
        Question(10578, "Combien de sortes de cactus existe-t-il?", listOf("500", "1000", "2000", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 2000 espèces de cactus dans le monde, principalement réparties sur le continent américain, des déserts aux forêts tropicales."),
        Question(10579, "Quel animal a les yeux les plus grands par rapport à sa taille?", listOf("La chouette", "La larve de libellule", "Le chaméléon", "L'aigle"), 1, "Nature", Difficulty.HARD, explanation = "Les yeux de la larve de libellule peuvent occuper jusqu'à 80 % de sa tête, ce qui lui offre une vision quasi panoramique pour chasser efficacement dans l'eau."),
        Question(10580, "Quel est le plus grand félin du monde?", listOf("Le lion", "Le tigre", "Le jaguar", "Le puma"), 1, "Nature", Difficulty.EASY, explanation = "Le tigre, notamment le tigre de Sibérie, peut peser jusqu'à 300 kg et mesurer plus de 3 mètres de long, ce qui en fait le plus grand félin, devant le lion."),
        Question(10581, "Combien de sortes de champignons existe-t-il?", listOf("10 000", "50 000", "150 000", "1 million"), 1, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ 50 000 espèces de champignons dans le monde, mais ce nombre pourrait être bien plus élevé, car de nombreuses espèces restent encore à découvrir."),
        Question(10582, "Quel animal peut courir le plus vite en marche arrière?", listOf("L'émeu", "l'autruche", "Le kangourou", "Le lièvre"), 0, "Nature", Difficulty.HARD, explanation = "L'émeu, un grand oiseau coureur d'Australie, peut courir en marche arrière aussi vite qu'en marche avant, atteignant jusqu'à 50 km/h."),
        Question(10583, "Quel est le plus grand crâne d'animal terrestre?", listOf("L'éléphant", "Le giraffe", "L'hippopotame", "Le rhinocéros"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le crâne de l'éléphant d'Afrique peut mesurer jusqu'à 2,5 mètres de long et peser plus de 500 kilogrammes, ce qui en fait le plus grand crâne d'animal terrestre."),
        Question(10584, "Combien de sortes de fougères existe-t-il?", listOf("1000", "5000", "12 000", "20 000"), 2, "Nature", Difficulty.HARD, explanation = "Les fougères sont des plantes vasculaires sans fleurs ni graines, et on estime qu'il existe environ 12 000 espèces différentes dans le monde."),
        Question(10585, "Quel animal peut tenir debout sur ses pattes arrière le plus longtemps?", listOf("Le kangourou", "Le suricate", "Le ours", "Le singe"), 3, "Nature", Difficulty.HARD, explanation = "Les singes, notamment les chimpanzés et les gorilles, peuvent se tenir debout sur leurs pattes arrière pendant de longues périodes grâce à leur musculature et leur équilibre adaptés à la bipédie occasionnelle."),
        Question(10586, "Quel est le plus grand mollusque gastéropode du monde?", listOf("L'escargot de Bourgogne", "L'escargot géant africain", "Le limaçon", "le poulpe"), 1, "Nature", Difficulty.HARD, explanation = "L'escargot géant africain (Achatina fulica) peut mesurer jusqu'à 30 cm de long et peser plus d'un kilogramme, ce qui en fait le plus grand gastéropode terrestre."),
        Question(10587, "Combien de sortes de palmiers existe-t-il?", listOf("500", "1000", "2500", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 2500 espèces de palmiers réparties dans le monde, principalement dans les régions tropicales et subtropicales."),
        Question(10588, "Quel animal peut nager le plus vite?", listOf("La baleine", "Le dauphin", "le poisson-voile", "la truite"), 2, "Nature", Difficulty.HARD, explanation = "Le poisson-voile peut atteindre 110 km/h en nageant, ce qui en fait le poisson le plus rapide du monde, grâce à sa grande nageoire dorsale et son corps fuselé."),
        Question(10589, "Quel est le plus grand herbivore du monde?", listOf("L'éléphant", "le giraffe", "L'hippopotame", "le rhinocéros"), 0, "Nature", Difficulty.EASY, explanation = "Les éléphants, notamment l'éléphant de savane d'Afrique, sont les plus grands herbivores terrestres, consommant jusqu'à 150 kg de végétation par jour."),
        Question(10590, "Combien de sortes de bactéries existe-t-il?", listOf("100", "1000", "10 000", "1 million"), 2, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ 10 000 espèces de bactéries identifiées, mais le nombre total pourrait être bien plus élevé, car la majorité reste inconnue."),
        Question(10591, "Quel animal peut sauter le plus haut par rapport à sa taille?", listOf("la sauterelle", "la puce", "le kangourou", "la grenouille"), 1, "Nature", Difficulty.HARD, explanation = "La puce peut sauter jusqu'à 200 fois sa propre hauteur, ce qui en fait le champion du saut proportionnel dans le règne animal."),
        Question(10592, "Quel est le plus grand carnivore terrestre?", listOf("le lion", "le tigre", "l'ours brun", "le puma"), 2, "Nature", Difficulty.MEDIUM, explanation = "L'ours brun, notamment la sous-espèce de l'ours Kodiak, peut peser jusqu'à 700 kg, ce qui en fait le plus grand mammifère terrestre exclusivement carnivore."),
        Question(10593, "Combien de sortes de lichens existe-t-il?", listOf("500", "5000", "20 000", "50 000"), 2, "Nature", Difficulty.HARD, explanation = "Les lichens sont des organismes symbiotiques très diversifiés, avec environ 20 000 espèces recensées dans le monde."),
        Question(10594, "Quel animal peut voir la plus grande portion du spectre lumineux?", listOf("l'humain", "l'abeille", "le chat", "l'aigle"), 1, "Nature", Difficulty.HARD, explanation = "Les abeilles perçoivent les ultraviolets, ce qui leur permet de voir une partie du spectre lumineux invisible pour les humains, incluant des motifs sur les fleurs."),
        Question(10595, "Quel est le plus grand écureuil du monde?", listOf("le marmotte", "le polatouche", "le grand écureuil volant", "le tamia"), 2, "Nature", Difficulty.HARD, explanation = "Le grand écureuil volant, originaire d'Asie du Sud-Est, peut mesurer jusqu'à 1,2 mètre de long, queue comprise, ce qui en fait le plus grand écureuil du monde."),
        Question(10596, "Combien de sortes de mousses existe-t-il?", listOf("500", "5000", "20 000", "30 000"), 3, "Nature", Difficulty.HARD, explanation = "Il existe environ 30 000 espèces de mousses dans le monde, ce qui en fait le deuxième groupe de plantes terrestres le plus diversifié après les plantes à fleurs."),
        Question(10597, "Quel animal peut se reproduire le plus rapidement?", listOf("le lapin", "la mouche", "le saumon", "le hérisson"), 1, "Nature", Difficulty.HARD, explanation = "La mouche domestique peut pondre jusqu'à 500 œufs en quelques jours, et son cycle de vie complet (de l'œuf à l'adulte) ne prend qu'environ une semaine, ce qui en fait l'animal à la reproduction la plus rapide."),
        Question(10598, "Quel est le plus grand édentés du monde?", listOf("le tatou géant", "le paresseux géant", "le fourmilier géant", "le pangolin"), 1, "Nature", Difficulty.HARD, explanation = "Le paresseux géant, aussi appelé paresseux terrestre, est le plus grand édenté ayant existé, mesurant jusqu'à 6 mètres de long et pesant plusieurs tonnes, contrairement aux paresseux modernes qui sont bien plus petits."),
        Question(10599, "Combien de sortes de fougères aquatiques existe-t-il?", listOf("10", "50", "200", "500"), 2, "Nature", Difficulty.HARD, explanation = "Les fougères aquatiques forment un groupe spécifique de plantes vasculaires adaptées aux milieux humides, avec environ 200 espèces réparties dans le monde."),
        Question(10600, "Quel animal peut se reproduire sans partenaire?", listOf("la bactérie", "le lézard sans queue", "le gecko", "la hyène"), 1, "Nature", Difficulty.HARD, explanation = "Certains lézards, comme le lézard sans queue, pratiquent la parthénogenèse, une reproduction asexuée où les femelles produisent des œufs fertiles sans mâle."),
        Question(10601, "Quel est l'animal le plus dangereux au monde?", listOf("le crocodile", "le requin", "le moustique", "le lion"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le moustique est considéré comme l'animal le plus dangereux car il transmet des maladies mortelles comme le paludisme, la dengue ou le chikungunya, causant des centaines de milliers de décès chaque année."),
        Question(10602, "Combien de dents ont les herbivores?", listOf("0", "12", "24", "32"), 2, "Nature", Difficulty.MEDIUM, explanation = "Contrairement aux carnivores, les herbivores comme les vaches ou les chevaux possèdent 24 molaires pour broyer les végétaux, sans incisives supérieures."),
        Question(10603, "Quel animal a le meilleur odorat?", listOf("le chien", "le requin", "l'ours", "le serpent"), 0, "Nature", Difficulty.EASY, explanation = "Le chien possède environ 300 millions de récepteurs olfactifs, contre 5 à 6 millions chez l'humain, ce qui en fait un animal au flair exceptionnel pour la chasse et le pistage."),
        Question(10604, "Quel est le plus grand amphibien du monde?", listOf("la salamandre géante du Japon", "la grenouille Goliath", "le triton géant", "la salamandre géante de Chine"), 3, "Nature", Difficulty.HARD, explanation = "La salamandre géante de Chine peut atteindre près de 1,80 mètre de long, ce qui en fait le plus grand amphibien connu. Elle vit dans les cours d'eau froids de Chine."),
        Question(10605, "Combien de temps peut-on survivre sans eau?", listOf("quelques heures", "quelques jours", "quelques semaines", "quelques mois"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le corps humain peut survivre environ trois jours sans eau, car l'eau est essentielle aux fonctions vitales comme la régulation de la température et l'élimination des déchets."),
        Question(10606, "Quel est le plus grand prédateur d'Afrique?", listOf("le lion", "la hyène", "le léopard", "l'aigle martial"), 0, "Nature", Difficulty.EASY, explanation = "Le lion est considéré comme le plus grand prédateur terrestre d'Afrique, dominant la chaîne alimentaire dans les savanes et les prairies."),
        Question(10607, "Combien de sortes de gaz existe-t-il dans l'atmosphère?", listOf("2", "5", "10", "Plus de 15"), 3, "Nature", Difficulty.HARD, explanation = "L'atmosphère terrestre est un mélange complexe contenant plus de 15 gaz différents, dont l'azote (78%) et l'oxygène (21%) sont majoritaires, mais aussi de nombreux gaz rares comme l'argon, le néon ou le xénon."),
        Question(10608, "Quel animal a le plus d'os dans son corps?", listOf("l'humain", "le serpent", "le poisson", "l'oiseau"), 2, "Nature", Difficulty.HARD, explanation = "Les poissons possèdent un squelette composé de nombreuses vertèbres et arêtes, ce qui leur donne souvent plus d'os que les mammifères ou les oiseaux."),
        Question(10609, "Quel est le plus grand rongeur d'Afrique?", listOf("le porc-épic", "le hérisson", "le cavy", "le castor"), 0, "Nature", Difficulty.HARD, explanation = "Le porc-épic d'Afrique peut peser jusqu'à 30 kg, ce qui en fait le plus grand rongeur du continent, devant le rat géant."),
        Question(10610, "Combien de temps un arbre peut-il vivre?", listOf("100 ans", "500 ans", "5000 ans", "10 000 ans"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le plus vieil arbre connu, un épicéa en Suède nommé Old Tjikko, a environ 9 500 ans. Certains pins bristlecone aux États-Unis dépassent 5 000 ans."),
        Question(10611, "Quel animal peut voir dans le noir?", listOf("le chat", "la chouette", "le chat et la chouette", "le requin"), 2, "Nature", Difficulty.EASY, explanation = "Les chats et les chouettes possèdent une vision nocturne très développée grâce à un tapis réflecteur dans leurs yeux, qui amplifie la lumière disponible."),
        Question(10612, "Quel est le plus grand désert de glace du monde?", listOf("l'Antarctique", "l'Arctique", "le Groenland", "la Sibérie"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'Antarctique est considéré comme le plus grand désert de glace car il s'agit d'un désert polaire recevant très peu de précipitations, avec une calotte glaciaire couvrant 98% de sa surface."),
        Question(10613, "Combien de sortes de dinosaures existaient-elles?", listOf("100", "500", "1000", "Plus de 900"), 3, "Nature", Difficulty.HARD, explanation = "Plus de 900 espèces de dinosaures ont été scientifiquement décrites à partir de fossiles, mais le nombre réel ayant existé est probablement bien plus élevé, car de nombreuses espèces n'ont pas laissé de traces."),
        Question(10614, "Quel animal peut dormir pendant des années?", listOf("l'ours", "la tortue", "l'escargot", "le crocodile"), 2, "Nature", Difficulty.HARD, explanation = "L'escargot peut hiberner ou entrer en estivation pendant plusieurs années si les conditions environnementales sont défavorables, comme la sécheresse ou le froid."),
        Question(10615, "Quel est le plus grand volcán du monde?", listOf("le Sakura-jima", "le Mauna Loa", "l'Etna", "le Krakatoa"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le Mauna Loa, à Hawaï, est le plus grand volcan du monde en volume et en superficie, s'élevant à plus de 9 000 mètres depuis le plancher océanique."),
        Question(10616, "Combien de tempo cardiaque a une baleine?", listOf("10-20 bpm", "40-60 bpm", "80-100 bpm", "120+ bpm"), 0, "Nature", Difficulty.HARD, explanation = "Le rythme cardiaque des baleines est très lent, entre 10 et 20 battements par minute, car leur métabolisme est adapté à la plongée profonde et à la conservation d'oxygène."),
        Question(10617, "Quel animal peut vivre dans le plus d'altitudes différentes?", listOf("le puma", "le mouton", "l'aigle", "la chèvre"), 3, "Nature", Difficulty.HARD, explanation = "Les chèvres sont capables de s'adapter à une large gamme d'altitudes, des plaines jusqu'à plus de 5 000 mètres dans l'Himalaya, grâce à leur physiologie robuste et leur agilité."),
        Question(10618, "Quel est le plus grand groupe d'îles du monde?", listOf("l'Indonésie", "l'Archipel du Japon", "les Philippines", "les Antilles"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'Indonésie est le plus grand archipel du monde avec plus de 17 000 îles, dont les plus célèbres sont Java, Sumatra et Bornéo."),
        Question(10619, "Combien de sortes de baleines existe-t-il?", listOf("5", "20", "90", "150"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 90 espèces de cétacés, un groupe qui inclut les baleines, les dauphins et les marsouins, classés en deux sous-ordres : les mysticètes (baleines à fanons) et les odontocètes (baleines à dents)."),
        Question(10620, "Quel animal peut produire le plus de lait?", listOf("la vache", "la baleine", "la chèvre", "la brebis"), 1, "Nature", Difficulty.HARD, explanation = "La baleine bleue, le plus grand animal du monde, produit jusqu'à 200 litres de lait par jour pour nourrir son baleineau, ce qui dépasse largement la production des vaches laitières."),
        Question(10621, "Quel est le plus long réseau fluvial du monde?", listOf("le Nil", "l'Amazone", "le Yangzi", "le Mississippi"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le Nil s'étend sur environ 6 650 kilomètres, traversant onze pays d'Afrique, ce qui en fait le plus long fleuve du monde, devant l'Amazone."),
        Question(10622, "Combien de sortes de loups existe-t-il?", listOf("2", "5", "10", "20"), 2, "Nature", Difficulty.HARD, explanation = "La classification scientifique actuelle reconnaît environ 10 espèces de loups, incluant le loup gris, le loup roux et le loup d'Abyssinie."),
        Question(10623, "Quel animal peut produire du poison mais n'est pas un serpent?", listOf("la grenouille", "le poisson-globe", "le papillon", "l'insecte"), 2, "Nature", Difficulty.HARD, explanation = "Certaines espèces de papillons, comme le papillon monarque, accumulent des toxines issues des plantes qu'ils consomment au stade chenille, ce qui les rend toxiques pour leurs prédateurs."),
        Question(10624, "Quel est le plus grand cristal naturel du monde?", listOf("le cristal de sélénite", "le cristal de quartz", "le cristal de diamant", "le cristal de calcite"), 0, "Nature", Difficulty.HARD, explanation = "Le plus grand cristal naturel du monde est un cristal de sélénite, découvert dans la grotte des Cristaux de Naica, au Mexique, mesurant jusqu'à 12 mètres de long."),
        Question(10625, "Combien de sortes d'antilopes existe-t-il?", listOf("10", "50", "100", "200"), 3, "Nature", Difficulty.HARD, explanation = "Le terme \"antilope\" regroupe environ 200 espèces de mammifères ruminants de la famille des bovidés, principalement présentes en Afrique et en Asie."),
        Question(10626, "Quel animal peut parler le mieux?", listOf("le perroquet", "le corbeau", "le dauphin", "le chimpanzé"), 0, "Nature", Difficulty.EASY, explanation = "Les perroquets possèdent un organe vocal appelé syrinx et une langue épaisse qui leur permet d'imiter la parole humaine avec une grande précision."),
        Question(10627, "Quel est le plus grand marais du monde?", listOf("le Pantanal", "les Everglades", "le Haut-Paraná", "le Danube"), 0, "Nature", Difficulty.HARD, explanation = "Le Pantanal, situé principalement au Brésil, est la plus grande zone humide du monde, s'étendant sur environ 150 000 km². Il dépasse le marais du Okavango en Afrique et les Everglades en Floride."),
        Question(10628, "Combien de sortes de salamandres existe-t-il?", listOf("100", "300", "600", "1000"), 3, "Nature", Difficulty.HARD, explanation = "Les salamandres forment une famille d'amphibiens qui compte environ 1000 espèces différentes à travers le monde, principalement dans les régions tempérées de l'hémisphère nord."),
        Question(10629, "Quel animal peut produire du miel mais n'est pas une abeille?", listOf("la guêpe", "le bourdon", "la fourmi", "la mouche"), 2, "Nature", Difficulty.HARD, explanation = "Certaines espèces de fourmis, comme les fourmis à miel, stockent du nectar dans leur abdomen pour nourrir la colonie, produisant ainsi une substance sucrée comparable au miel."),
        Question(10630, "Quel est le plus grand tremblement de terre jamais enregistré?", listOf("8.0", "8.5", "9.0", "9.5"), 3, "Nature", Difficulty.HARD, explanation = "Le tremblement de terre de Valdivia au Chili en 1960 a atteint une magnitude de 9,5 sur l'échelle de Richter, ce qui en fait le plus puissant jamais enregistré par des instruments sismologiques."),
        Question(10631, "Combien de sortes de crevettes existe-t-il?", listOf("100", "500", "2000", "3000"), 3, "Nature", Difficulty.HARD, explanation = "On recense environ 3000 espèces de crevettes dans le monde, réparties dans les eaux marines et douces."),
        Question(10632, "Quel animal peut changer de sexe?", listOf("le poisson-clown", "le mérou", "le poisson perroquet", "Tous les poissons"), 3, "Nature", Difficulty.HARD, explanation = "De nombreux poissons, comme les mérous ou les poissons-clowns, sont hermaphrodites séquentiels et peuvent changer de sexe au cours de leur vie, souvent en fonction de la structure sociale ou de la taille."),
        Question(10633, "Quel est le plus grand récif de corail du monde?", listOf("la Grande Barrière de Corail", "le récif de Belize", "le récif de Mésoamérique", "le récif de Caraïbes"), 0, "Nature", Difficulty.EASY, explanation = "La Grande Barrière de Corail, située au large de l'Australie, s'étend sur plus de 2 300 kilomètres et est visible depuis l'espace."),
        Question(10634, "Combien de sortes de mousques existe-t-il?", listOf("10", "100", "3500", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 3500 espèces de mousses dans le monde, un groupe de plantes non vasculaires qui poussent dans des environnements humides et ombragés."),
        Question(10635, "Quel animal peut produire du soie?", listOf("l'araignée", "la chenille", "la mouche", "le papillon"), 1, "Nature", Difficulty.MEDIUM, explanation = "La soie est produite par la chenille du ver à soie (Bombyx mori) qui tisse un cocon pour se protéger lors de sa métamorphose."),
        Question(10636, "Quel est le plus grand lac intérieur du monde?", listOf("le lac Tanganyika", "le lac Supérieur", "le lac Victoria", "la mer Caspienne"), 3, "Nature", Difficulty.MEDIUM, explanation = "La mer Caspienne, bien que salée, est considérée comme un lac car elle est entièrement entourée de terres. Sa superficie d'environ 371 000 km² en fait le plus grand lac intérieur du monde."),
        Question(10637, "Combien de sortes de lézards existe-t-il?", listOf("500", "2000", "6500", "10 000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 6500 espèces de lézards dans le monde, ce qui en fait le groupe le plus diversifié des reptiles après les serpents."),
        Question(10638, "Quel animal peut produire du feu?", listOf("le poisson des abysses", "le scarabée bombardier", "aucun", "le bombardier noir"), 2, "Nature", Difficulty.HARD, explanation = "Aucun animal ne peut produire du feu de manière naturelle. Le mythe des dragons cracheurs de feu est une invention légendaire sans fondement scientifique."),
        Question(10639, "Quel est le plus grand écosystème du monde?", listOf("la forêt amazonienne", "l'océan", "la savane africaine", "la toundra"), 1, "Nature", Difficulty.HARD, explanation = "L'océan couvre plus de 70% de la surface terrestre et abrite la plus grande diversité de vie, ce qui en fait le plus grand écosystème de la planète."),
        Question(10640, "Combien de sortes de poissons d'eau douce existe-t-il?", listOf("500", "2000", "15 000", "30 000"), 2, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ 15 000 espèces de poissons d'eau douce dans le monde, ce qui représente plus de 40 % de toutes les espèces de poissons connues."),
        Question(10641, "Quel animal peut courir le plus vite en sprinting?", listOf("le guépard", "l'antilope", "le léopard", "le lion"), 0, "Nature", Difficulty.EASY, explanation = "Le guépard peut atteindre des pointes de vitesse de 110 à 120 km/h en sprint, ce qui en fait le mammifère terrestre le plus rapide. Cette adaptation est due à son corps léger, ses longues pattes et sa colonne vertébrale flexible."),
        Question(10642, "Quel est le plus grand système de montagnes sous-marines?", listOf("la dorsale médio-océanique", "la chaîne des Mariannes", "le rift océanique", "la fosse de Tonga"), 0, "Nature", Difficulty.HARD, explanation = "La dorsale médio-océanique est une chaîne de montagnes sous-marines qui s'étend sur plus de 65 000 kilomètres à travers tous les océans, formée par le mouvement des plaques tectoniques."),
        Question(10643, "Combien de sortes d'araignées existe-t-il?", listOf("1000", "5000", "50 000", "100 000"), 2, "Nature", Difficulty.HARD, explanation = "Plus de 50 000 espèces d'araignées ont été recensées dans le monde, réparties dans 129 familles."),
        Question(10644, "Quel animal peut voler le plus haut?", listOf("l'aigle", "la cigogne", "le condor", "l'oie"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le condor des Andes peut atteindre des altitudes de plus de 6 500 mètres grâce à ses ailes immenses et aux courants thermiques."),
        Question(10645, "Quel est le plus grand bassin versant du monde?", listOf("l'Amazone", "le Congo", "le Yangtze", "le Mississipi"), 0, "Nature", Difficulty.HARD, explanation = "Le bassin de l'Amazone couvre environ 7 millions de km², s'étendant sur plusieurs pays d'Amérique du Sud, ce qui en fait le plus vaste réseau hydrographique de la planète."),
        Question(10646, "Combien de sortes de termites existe-t-il?", listOf("50", "100", "2600", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 2600 espèces de termites recensées dans le monde, principalement dans les régions tropicales et subtropicales."),
        Question(10647, "Quel animal peut émettre une décharge électrique?", listOf("l'anguille électrique", "la raie électrique", "le poisson-électrique", "Tous ces animaux"), 3, "Nature", Difficulty.MEDIUM, explanation = "Plusieurs espèces aquatiques, comme les anguilles électriques, les raies torpilles et certains poissons-chats, possèdent des organes spécialisés capables de produire des décharges électriques pour la défense ou la chasse."),
        Question(10648, "Quel est le plus grand gisement de minéraux du monde?", listOf("l'Australie", "la Russie", "le Brésil", "la Suisse"), 0, "Nature", Difficulty.HARD, explanation = "L'Australie possède les plus vastes réserves de minerais au monde, notamment de fer, d'or et d'uranium, avec des gisements majeurs comme ceux de Pilbara et d'Olympic Dam."),
        Question(10649, "Combien de sortes de vers existe-t-il?", listOf("500", "2000", "20 000", "100 000"), 3, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ 100 000 espèces de vers dans le monde, incluant les vers de terre, les vers plats et les vers ronds, bien que ce nombre puisse varier selon les classifications scientifiques."),
        Question(10650, "Quel animal peut contrôler sa température corporelle le mieux?", listOf("l'ours", "le dauphin", "l'humain", "le pingouin"), 1, "Nature", Difficulty.HARD, explanation = "Les dauphins sont des mammifères marins homéothermes qui maintiennent une température corporelle stable grâce à une épaisse couche de graisse et un système circulatoire adapté, même dans les eaux froides."),
        Question(10651, "Quel est le plus grand glacier du monde?", listOf("la calotte glaciaire de l'Antarctique", "la calotte glaciaire du Groenland", "le glacier de l'Eurasie", "le glacier de Patagonie"), 0, "Nature", Difficulty.MEDIUM, explanation = "La calotte glaciaire de l'Antarctique s'étend sur environ 14 millions de km², ce qui en fait la plus grande masse de glace au monde, bien plus vaste que tout glacier individuel."),
        Question(10652, "Combien de sortes d'escargots existe-t-il?", listOf("500", "2000", "24 000", "43 000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 24 000 espèces d'escargots dans le monde, réparties entre escargots terrestres, marins et d'eau douce."),
        Question(10653, "Quel animal peut retenir l'air le plus longtemps?", listOf("le humain", "le phoque", "la baleine", "le dauphin"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les baleines peuvent retenir leur souffle jusqu'à 90 minutes lors de plongées profondes, grâce à une capacité pulmonaire adaptée et un métabolisme ralenti."),
        Question(10654, "Quel est le plus grand désert de sable du monde?", listOf("le Sahara", "le désert de Kalahari", "le désert d'Arabie", "le désert de Gobi"), 0, "Nature", Difficulty.EASY, explanation = "Le Sahara est le plus grand désert de sable du monde, s'étendant sur environ 9,2 millions de kilomètres carrés en Afrique du Nord."),
        Question(10655, "Combien de sortes de poissons-papillons existe-t-il?", listOf("100", "200", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les poissons-papillons, reconnaissables à leurs couleurs vives et motifs, comptent environ 500 espèces réparties principalement dans les récifs coralliens tropicaux."),
        Question(10656, "Quel animal peut produire le plus d'œufs?", listOf("la poule", "le poisson", "la reine des fourmis", "la méduse"), 3, "Nature", Difficulty.HARD, explanation = "La méduse peut pondre jusqu'à 45 000 œufs par jour, ce qui en fait l'animal le plus prolifique en termes de production d'œufs."),
        Question(10657, "Quel est le plus grand lac salé du monde?", listOf("la mer Morte", "la mer Caspienne", "la mer d'Aral", "le lac Salton"), 1, "Nature", Difficulty.HARD, explanation = "La mer Caspienne est considérée comme le plus grand lac salé du monde en raison de sa superficie d'environ 371 000 km², bien qu'elle soit souvent qualifiée de mer en raison de sa taille et de sa salinité."),
        Question(10658, "Combien de sortes de dorades existe-t-il?", listOf("10", "50", "100", "300"), 3, "Nature", Difficulty.HARD, explanation = "Le terme \"dorade\" regroupe plusieurs espèces de poissons de la famille des Sparidés, dont environ 300 espèces sont répertoriées dans le monde, principalement dans les eaux tempérées et tropicales."),
        Question(10659, "Quel animal a le plus d'yeux?", listOf("l'araignée", "la chauve-souris", "la mouche", "la libellule"), 2, "Nature", Difficulty.HARD, explanation = "Les mouches possèdent des yeux composés formés de milliers de petites unités visuelles appelées ommatidies, ce qui leur confère un nombre d'yeux bien supérieur à celui de la plupart des autres animaux."),
        Question(10660, "Quel est le plus grand îlot du monde?", listOf("la Nouvelle-Zélande", "la Grande-Bretagne", "Madagascar", "Bornéo"), 3, "Nature", Difficulty.HARD, explanation = "Bornéo est la troisième plus grande île du monde, mais elle est considérée comme le plus grand îlot car elle est partagée entre trois pays : l'Indonésie, la Malaisie et le Brunei."),
        Question(10661, "Combien de sortes de raies existe-t-il?", listOf("100", "300", "600", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 600 espèces de raies dans le monde, réparties dans les océans et certaines eaux douces, incluant des variétés comme la raie manta et la raie pastenague."),
        Question(10662, "Quel animal peut être actif la plus longtemps sans sommeil?", listOf("la grenouille à pinceaux", "le requin", "la libellule", "l'insecte"), 2, "Nature", Difficulty.HARD, explanation = "Les libellules peuvent rester actives plusieurs semaines sans dormir, car leur métabolisme et leur système nerveux leur permettent de fonctionner en continu."),
        Question(10663, "Quel est le plus grand golfstream du monde?", listOf("le Gulf Stream", "le Kuroshio", "le Agulhas", "le Humboldt"), 0, "Nature", Difficulty.HARD, explanation = "Le Gulf Stream est un courant océanique chaud de l'Atlantique Nord, le plus puissant au monde en termes de débit d'eau."),
        Question(10664, "Combien de sortes de poulpes existe-t-il?", listOf("50", "200", "300", "500"), 2, "Nature", Difficulty.HARD, explanation = "Environ 300 espèces de poulpes sont répertoriées dans le monde, vivant dans tous les océans, des eaux côtières peu profondes aux abysses."),
        Question(10665, "Quel animal peut avoir le plus long cri?", listOf("la baleine", "le loup", "le lion", "l'éléphant"), 0, "Nature", Difficulty.HARD, explanation = "Le cri de la baleine bleue peut atteindre 188 décibels et parcourir des centaines de kilomètres sous l'eau, ce qui en fait le cri animal le plus long et le plus puissant."),
        Question(10666, "Quel est le plus grand point culminant sous-marin du monde?", listOf("l'Everest sous-marin", "le pic Lomonosov", "le mont Tamu", "le mont Hess"), 2, "Nature", Difficulty.HARD, explanation = "Le mont Tamu est un volcan sous-marin situé dans l'océan Pacifique, dont le sommet atteint environ 4 000 mètres sous la surface, ce qui en fait le plus grand point culminant sous-marin connu."),
        Question(10667, "Combien de sortes de crabes existe-t-il?", listOf("500", "1000", "6500", "10 000"), 2, "Nature", Difficulty.HARD, explanation = "Plus de 6 500 espèces de crabes sont recensées dans le monde, réparties dans les océans, les eaux douces et sur terre."),
        Question(10668, "Quel animal peut avoir les plus longues défenses?", listOf("l'éléphant", "le morse", "le narval", "le sanglier"), 2, "Nature", Difficulty.MEDIUM, explanation = "La défense du narval est en fait une dent incisive qui peut atteindre jusqu'à 3 mètres de long, ce qui en fait la plus longue défense du règne animal."),
        Question(10669, "Quel est le plus haut volcan du monde?", listOf("le Mauna Kea", "le Popocatépetl", "le Mauna Loa", "l'Ojos del Salado"), 3, "Nature", Difficulty.HARD, explanation = "L'Ojos del Salado, situé à la frontière entre le Chili et l'Argentine, culmine à 6 893 mètres d'altitude, ce qui en fait le plus haut volcan actif de la planète."),
        Question(10670, "Combien de sortes d'huîtres existe-t-il?", listOf("10", "50", "200", "500"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 200 espèces d'huîtres dans le monde, réparties dans les eaux marines et saumâtres des différentes régions."),
        Question(10671, "Quel animal peut avoir le plus gros cerveau par rapport à son corps?", listOf("l'humain", "le dauphin", "le perroquet", "l'éléphant"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'humain possède le plus gros cerveau proportionnellement à son corps parmi tous les animaux, avec un ratio d'environ 2 % de sa masse corporelle."),
        Question(10672, "Quel est le plus grand glacier d'Afrique?", listOf("le Kilimandjaro", "le Mont-Blanc", "les Rwenzori", "les Drakensberg"), 0, "Nature", Difficulty.HARD, explanation = "Le Kilimandjaro abrite le plus grand glacier d'Afrique, bien que sa calotte glaciaire diminue rapidement à cause du réchauffement climatique."),
        Question(10673, "Combien de sortes de bivalves existe-t-il?", listOf("500", "1000", "5000", "15 000"), 3, "Nature", Difficulty.HARD, explanation = "Les bivalves, comme les moules et les huîtres, comptent environ 15 000 espèces décrites dans le monde, réparties dans divers habitats marins et d'eau douce."),
        Question(10674, "Quel animal peut avoir la plus longue vie reproductive?", listOf("l'humain", "le perroquet", "la tortue", "la baleine"), 2, "Nature", Difficulty.HARD, explanation = "Les tortues marines et terrestres sont connues pour leur longévité exceptionnelle, certaines espèces pouvant se reproduire jusqu'à un âge avancé, dépassant souvent 50 ans de capacité reproductive active."),
        Question(10675, "Quel est le plus grand acteur du changement climatique?", listOf("le CO2", "le méthane", "le dioxyde de soufre", "la vapeur d'eau"), 3, "Nature", Difficulty.HARD, explanation = "La vapeur d’eau est le gaz à effet de serre le plus abondant dans l’atmosphère, responsable d’environ 60 % de l’effet de serre naturel, amplifiant le réchauffement via une boucle de rétroaction positive."),
        Question(10676, "Combien de sortes de calmars existe-t-il?", listOf("50", "200", "300", "500"), 2, "Nature", Difficulty.HARD, explanation = "On dénombre environ 300 espèces de calmars dans le monde, allant des petites espèces côtières aux calmars géants des profondeurs."),
        Question(10677, "Quel animal peut avoir la meilleure vision périphérique?", listOf("le faucon", "le lapin", "la chèvre", "le cheval"), 3, "Nature", Difficulty.HARD, explanation = "Les yeux du cheval sont placés sur les côtés de sa tête, ce qui lui offre un champ de vision d'environ 350 degrés, lui permettant de voir presque tout autour de lui sans bouger la tête."),
        Question(10678, "Quel est le plus grand système de grottes du monde?", listOf("Mammoth Cave", "Carlsbad Caverns", "Son Doong", "Batu Caves"), 0, "Nature", Difficulty.HARD, explanation = "Mammoth Cave, situé dans le Kentucky aux États-Unis, détient ce record avec plus de 650 kilomètres de passages cartographiés."),
        Question(10679, "Combien de sortes de moules existe-t-il?", listOf("100", "500", "1000", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Le terme \"moule\" désigne un grand groupe de mollusques bivalves, et on estime qu'il existe environ 1 000 espèces différentes de moules à travers le monde, réparties dans les eaux marines et douces."),
        Question(10680, "Quel animal peut avoir la plus grande taille de litter?", listOf("le phoque", "la baleine", "la souris", "le poisson"), 2, "Nature", Difficulty.HARD, explanation = "Les souris peuvent avoir des portées allant jusqu'à une vingtaine de petits, ce qui est exceptionnellement élevé pour leur taille."),
        Question(10681, "Quel est le plus grand récif de corail d'eau douce du monde?", listOf("il n'y en a pas", "le lac Tanganyika", "le lac Victoria", "l'Amazone"), 0, "Nature", Difficulty.HARD, explanation = "Les coraux d'eau douce n'existent pas : les récifs coralliens sont exclusivement marins, car les polypes coralliens ont besoin d'eau salée pour survivre."),
        Question(10682, "Combien de sortes d'anémones de mer existe-t-il?", listOf("50", "200", "1000", "1100"), 3, "Nature", Difficulty.HARD, explanation = "Il existe environ 1 100 espèces d'anémones de mer recensées dans le monde, vivant principalement dans les eaux marines peu profondes."),
        Question(10683, "Quel animal peut avoir les nageoires les plus grandes?", listOf("la raie manta", "le poisson-voile", "le poisson-papillon", "le poisson-ange"), 0, "Nature", Difficulty.HARD, explanation = "La raie manta possède les plus grandes nageoires pectorales parmi les poissons, pouvant atteindre jusqu'à 7 mètres d'envergure, ce qui lui permet de planer gracieusement dans l'eau."),
        Question(10684, "Quel est le plus grand système de sources thermales du monde?", listOf("Yellowstone", "la Vallée de la Mort", "le Geyser Valley", "le Beppu"), 0, "Nature", Difficulty.HARD, explanation = "Yellowstone abrite le plus vaste ensemble de sources chaudes et geysers actifs de la planète, avec plus de 10 000 formations géothermiques."),
        Question(10685, "Combien de sortes de conchs existe-t-il?", listOf("100", "300", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Le terme \"conch\" désigne plusieurs espèces de mollusques marins de la famille des Strombidae, et on en recense environ 500 espèces dans le monde."),
        Question(10686, "Quel animal peut avoir la queue la plus longue par rapport à son corps?", listOf("le lion", "le chat", "le poisson-longarina", "la comète"), 2, "Nature", Difficulty.HARD, explanation = "La longarina, ou poisson-lune queue-de-lyre, possède une queue pouvant atteindre plusieurs fois la longueur de son corps, ce qui en fait le détenteur du record de proportion queue/corps chez les animaux."),
        Question(10687, "Quel est le plus grand gisement de pétrole du monde?", listOf("le Ghawar", "le Cantarell", "le Burgan", "le Safaniyah"), 0, "Nature", Difficulty.HARD, explanation = "Le gisement de Ghawar, situé en Arabie saoudite, est le plus grand champ pétrolier conventionnel jamais découvert, avec des réserves estimées à plus de 70 milliards de barils."),
        Question(10688, "Combien de sortes de nudibranches existe-t-il?", listOf("100", "500", "3000", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Les nudibranches, mollusques gastéropodes marins, comptent environ 3000 espèces décrites dans le monde, réparties dans divers océans et habitats."),
        Question(10689, "Quel animal peut avoir les patins les plus larges par rapport à son poids?", listOf("le lièvre", "le renne", "l'orignal", "le castor"), 0, "Nature", Difficulty.HARD, explanation = "Les pattes du lièvre arctique sont larges et couvertes de poils, agissant comme des raquettes pour répartir son poids sur la neige molle et éviter de s'enfoncer."),
        Question(10690, "Quel est le plus grand dépôt de sel du monde?", listOf("le Salar", "le Lac Rose", "la Mer Morte", "Bonneville Salt Flats"), 0, "Nature", Difficulty.HARD, explanation = "Le Salar d'Uyuni en Bolivie est le plus grand désert de sel du monde, s'étendant sur plus de 10 000 km²."),
        Question(10691, "Combien de sortes de pennatules existe-t-il?", listOf("50", "200", "300", "500"), 2, "Nature", Difficulty.HARD, explanation = "Les pennatules, aussi appelées plumes de mer, sont des cnidaires coloniaux. On en dénombre environ 300 espèces différentes dans les océans du monde."),
        Question(10692, "Quel animal peut avoir les griffes les plus longues?", listOf("l'ours", "le pangolin", "le paresseux", "l'oryctérope"), 2, "Nature", Difficulty.HARD, explanation = "Les paresseux ont des griffes pouvant atteindre jusqu'à 10 centimètres, adaptées pour se suspendre aux branches et se déplacer lentement dans les arbres."),
        Question(10693, "Quel est le plus grand gisement d'or du monde?", listOf("Carlin Trend", "Witwatersrand", "Kalgoorlie", "Sukhoi Log"), 0, "Nature", Difficulty.HARD, explanation = "Situé dans le Nevada, aux États-Unis, le Carlin Trend est une ceinture géologique qui produit depuis les années 1960 la plus grande quantité d'or au monde, grâce à des gisements sédimentaires uniques."),
        Question(10694, "Combien de sortes de gorgones existe-t-il?", listOf("50", "200", "800", "1500"), 2, "Nature", Difficulty.HARD, explanation = "Les gorgones, aussi appelées coraux cornés ou coraux mous, comptent environ 800 espèces réparties dans les océans du monde."),
        Question(10695, "Quel animal peut avoir la membrane alaire la plus grande?", listOf("la chauve-souris", "le ptéranodon", "le caïman noir", "la raie manta"), 0, "Nature", Difficulty.HARD, explanation = "La membrane alaire des chauves-souris, appelée patagium, s'étend entre les doigts allongés, leur permettant d'atteindre la plus grande envergure parmi les mammifères volants."),
        Question(10696, "Quel est le plus grand dépôt de cuivre du monde?", listOf("Escondida", "La Tinta", "Antapaccay", "Chuquicamata"), 0, "Nature", Difficulty.HARD, explanation = "Située dans le désert d'Atacama au Chili, la mine d'Escondida est la plus grande mine de cuivre du monde en termes de production, exploitée par BHP Billiton, Rio Tinto et un consortium japonais."),
        Question(10697, "Combien de sortes d'étoiles de mer existe-t-il?", listOf("500", "1000", "2000", "7000"), 3, "Nature", Difficulty.HARD, explanation = "Il existe environ 7000 espèces d'étoiles de mer recensées dans les océans du monde, variant en taille, couleur et nombre de bras."),
        Question(10698, "Quel animal peut avoir les dents les plus tranchantes?", listOf("le requin", "la piranha", "la loutre", "le castor"), 1, "Nature", Difficulty.HARD, explanation = "Les piranhas possèdent des dents triangulaires et acérées capables de déchirer la chair avec une grande efficacité, ce qui leur confère une réputation de morsure redoutable dans leur environnement aquatique."),
        Question(10699, "Quel est le plus grand dépôt de diamant du monde?", listOf("Argyle", "Jwaneng", "Ekati", "Victor"), 0, "Nature", Difficulty.HARD, explanation = "La mine d'Argyle, en Australie-Occidentale, est le plus grand gisement de diamants au monde en volume, bien qu'elle produise principalement des diamants de qualité industrielle."),
        Question(10700, "Combien de sortes d'oursins existe-t-il?", listOf("300", "500", "1000", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 1 000 espèces d'oursins réparties dans tous les océans du monde, des eaux peu profondes aux grandes profondeurs."),
        Question(10701, "Quel animal peut avoir les oreilles les plus sensibles?", listOf("la chauve-souris", "le chat", "l'éléphant", "la chouette"), 0, "Nature", Difficulty.HARD, explanation = "Les chauves-souris utilisent l'écholocation, émettant des ultrasons et analysant leurs échos pour se déplacer et chasser, ce qui nécessite une ouïe extrêmement fine."),
        Question(10702, "Quelle est la plus grande chaîne de montagnes du monde?", listOf("l'Himalaya", "les Andes", "la Cordillère des Andes", "les Rocheuses"), 1, "Nature", Difficulty.EASY, explanation = "Les Andes s'étendent sur plus de 7 000 kilomètres le long de la côte ouest de l'Amérique du Sud, ce qui en fait la plus longue chaîne de montagnes continentale du monde."),
        Question(10703, "Combien de sortes de concombre de mer existe-t-il?", listOf("100", "300", "1000", "1500"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 1000 espèces de concombres de mer dans le monde, réparties dans tous les océans, des eaux peu profondes aux abysses."),
        Question(10704, "Quel animal peut avoir les narines les plus mobiles?", listOf("le chameau", "le cheval", "l'éléphant", "le lion"), 0, "Nature", Difficulty.HARD, explanation = "Les chameaux possèdent des narines très mobiles qu'ils peuvent ouvrir et fermer à volonté pour se protéger du sable lors des tempêtes dans le désert."),
        Question(10705, "Quel est le plus grand dépôt de charbon du monde?", listOf("la Chine", "la Russie", "l'Australie", "l'Afrique du Sud"), 0, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus grandes réserves de charbon au monde, concentrées notamment dans les provinces du Shanxi et du Shaanxi, ce qui en fait le premier producteur et consommateur mondial de cette ressource."),
        Question(10706, "Combien de sortes de lys de mer existe-t-il?", listOf("50", "200", "600", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les lys de mer, ou crinoïdes, sont des échinodermes marins anciens, et environ 600 espèces vivantes sont recensées aujourd'hui."),
        Question(10707, "Quel animal peut avoir les yeux les plus mobiles?", listOf("le caméléon", "la chauve-souris", "le poisson-globe", "le poisson-archer"), 0, "Nature", Difficulty.HARD, explanation = "Le caméléon possède des yeux capables de bouger indépendamment l'un de l'autre, avec un champ de vision à 360 degrés et une mise au point rapide."),
        Question(10708, "Quel est le plus grand dépôt d'argent du monde?", listOf("Antamina", "Escondida", "Cannington", "Pershing"), 2, "Nature", Difficulty.HARD, explanation = "La mine de Cannington, située dans le Queensland en Australie, est le plus grand gisement d'argent connu au monde, avec des réserves estimées à plusieurs centaines de millions d'onces."),
        Question(10709, "Combien de sortes de balanes existe-t-il?", listOf("500", "1000", "1200", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 1200 espèces de balanes, des crustacés marins fixés souvent confondus avec des coquillages."),
        Question(10710, "Quel animal peut avoir les pupilles les plus grandes?", listOf("la chauve-souris", "le chat", "le loup", "l'ours"), 0, "Nature", Difficulty.HARD, explanation = "La chauve-souris possède les plus grandes pupilles proportionnellement à la taille de son corps parmi les mammifères, ce qui optimise sa vision nocturne pour chasser dans l'obscurité."),
        Question(10711, "Quel est le plus grand dépôt d'uranium du monde?", listOf("Kazakhstan", "Canada", "Namibie", "Australie"), 0, "Nature", Difficulty.HARD, explanation = "Le Kazakhstan possède les plus grandes réserves d'uranium au monde, notamment dans la région du bassin de Chu-Sarysu, et en est le premier producteur mondial depuis 2009."),
        Question(10712, "Combien de sortes de crevettes-mantis existe-t-il?", listOf("100", "300", "600", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les crevettes-mantis, ou stomatopodes, comptent environ 600 espèces répertoriées dans le monde, principalement dans les eaux tropicales et subtropicales."),
        Question(10713, "Quel animal peut avoir la pupille la plus dilatée?", listOf("la chauve-souris", "la chouette", "le hibou", "le chat"), 1, "Nature", Difficulty.HARD, explanation = "La chouette possède une pupille extrêmement dilatable pour capter un maximum de lumière lors de ses chasses nocturnes, ce qui lui confère une excellente vision dans l'obscurité."),
        Question(10714, "Quel est le plus grand dépôt de zinc du monde?", listOf("Aitik", "Fridays", "Zafranal", "Antamina"), 3, "Nature", Difficulty.HARD, explanation = "La mine d'Antamina, située au Pérou, est l'une des plus grandes mines de zinc au monde, produisant également du cuivre et d'autres métaux."),
        Question(10715, "Combien de sortes de mollusques bivalves existe-t-il?", listOf("500", "2000", "3500", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 3500 espèces de mollusques bivalves, un groupe qui inclut les moules, huîtres, palourdes et coquilles Saint-Jacques."),
        Question(10716, "Quel animal peut avoir la meilleure vision nocturne?", listOf("la chouette", "la chauve-souris", "le loup", "le chat"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les yeux de la chouette contiennent un nombre élevé de bâtonnets, cellules photoréceptrices très sensibles à la lumière, et un tapetum lucidum qui réfléchit la lumière, lui offrant une vision nocturne exceptionnelle pour chasser dans l'obscurité."),
        Question(10717, "Quel est le plus grand dépôt de nickel du monde?", listOf("la Russie", "l'Australie", "l'Indonésie", "le Canada"), 1, "Nature", Difficulty.HARD, explanation = "L'Australie abrite le plus grand dépôt de nickel au monde, situé dans la région de Kalgoorlie, en Australie-Occidentale, avec des réserves estimées à plusieurs millions de tonnes."),
        Question(10718, "Combien de sortes de crevettes royales existe-t-il?", listOf("5", "10", "20", "50"), 2, "Nature", Difficulty.HARD, explanation = "La crevette royale est une appellation commerciale qui regroupe environ 20 espèces différentes du genre Penaeus, principalement élevées ou pêchées pour la consommation."),
        Question(10719, "Quel animal peut avoir la meilleure vision en couleur?", listOf("l'abeille", "le perroquet", "le mantis", "le poisson"), 3, "Nature", Difficulty.HARD, explanation = "Certains poissons, comme le poisson-mandarin, possèdent jusqu'à quatre types de cônes dans leurs yeux, leur permettant de voir plus de couleurs que les humains."),
        Question(10720, "Quel est le plus grand dépôt de platine du monde?", listOf("la Russie", "l'Afrique du Sud", "le Zimbabwe", "le Canada"), 1, "Nature", Difficulty.HARD, explanation = "L'Afrique du Sud possède le complexe du Bushveld, qui contient environ 70% des réserves mondiales de platine."),
        Question(10721, "Combien de sortes de coquilles Saint-Jacques existe-t-il?", listOf("50", "200", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "La coquille Saint-Jacques désigne en réalité plusieurs espèces du genre Pecten, dont environ 500 variétés sont répertoriées dans le monde, principalement dans les eaux tempérées et froides."),
        Question(10722, "Quel animal peut avoir la plus grande surface rétinienne par rapport à son œil?", listOf("l'aigle", "le faucon", "la libellule", "l'araignée"), 2, "Nature", Difficulty.HARD, explanation = "Les libellules possèdent des yeux composés géants qui couvrent presque toute leur tête, chaque œil contenant jusqu'à 30 000 facettes, ce qui leur offre un champ de vision quasi total de 360 degrés."),
        Question(10723, "Quel est le plus grand dépôt de cobalt du monde?", listOf("la République Démocratique du Congo", "la Chine", "la Russie", "l'Afrique du Sud"), 0, "Nature", Difficulty.HARD, explanation = "La République Démocratique du Congo possède les plus grandes réserves mondiales de cobalt, concentrées dans la région du Katanga, représentant environ 50% des ressources globales."),
        Question(10724, "Combien de sortes de pectens existe-t-il?", listOf("100", "300", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les pectens, ou pétoncles, comptent environ 500 espèces vivantes réparties dans les océans du monde entier."),
        Question(10725, "Quel animal peut avoir la meilleure acuité visuelle?", listOf("l'aigle", "le faucon pèlerin", "le mercredi", "l'autruche"), 1, "Nature", Difficulty.HARD, explanation = "Le faucon pèlerin possède une vision capable de repérer une proie à plus d'un kilomètre, grâce à une densité exceptionnelle de photorécepteurs dans sa rétine."),
        Question(10726, "Quel est le plus grand dépôt de manganèse du monde?", listOf("l'Afrique du Sud", "la Russie", "l'Australie", "l'Ukraine"), 0, "Nature", Difficulty.HARD, explanation = "L'Afrique du Sud possède le plus grand dépôt de manganèse au monde, situé dans le bassin du Kalahari, qui contient environ 80 % des réserves mondiales connues."),
        Question(10727, "Combien de sortes d'huître perlière existe-t-il?", listOf("5", "10", "20", "50"), 2, "Nature", Difficulty.HARD, explanation = "Il existe environ 20 espèces d'huîtres perlières, principalement des genres Pinctada et Pteria, qui produisent des perles naturelles."),
        Question(10728, "Quel animal peut avoir la plus grande résolution rétinienne?", listOf("le faucon", "l'aigle", "la mouche", "le mantis"), 0, "Nature", Difficulty.HARD, explanation = "Le faucon possède une densité exceptionnelle de photorécepteurs dans sa rétine, lui offrant une acuité visuelle jusqu'à huit fois supérieure à celle de l'humain."),
        Question(10729, "Quel est le plus grand dépôt de lithium du monde?", listOf("la Chili", "l'Argentine", "la Bolivie", "l'Australie"), 0, "Nature", Difficulty.HARD, explanation = "Le Chili abrite le plus grand dépôt de lithium au monde dans le salar d'Atacama, qui concentre environ 40% des réserves mondiales de ce métal essentiel aux batteries."),
        Question(10730, "Combien de sortes de palourdes existe-t-il?", listOf("100", "500", "1000", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Les palourdes désignent un groupe très large de mollusques bivalves marins, avec environ 1 000 espèces répertoriées dans le monde."),
        Question(10731, "Quel animal peut avoir le plus large spectre de sensibilité lumineuse?", listOf("le mantis", "l'abeille", "le poisson", "la mouche"), 0, "Nature", Difficulty.HARD, explanation = "La mante crevette possède jusqu'à 16 types de photorécepteurs, contre trois pour l'humain, lui permettant de percevoir une gamme exceptionnelle de couleurs et de lumières polarisées."),
        Question(10732, "Quel est le plus grand dépôt d'étain du monde?", listOf("la Chine", "l'Indonésie", "la Malaisie", "la Birmanie"), 1, "Nature", Difficulty.HARD, explanation = "L'Indonésie possède les plus grandes réserves d'étain au monde, principalement concentrées dans les îles de Bangka et Belitung."),
        Question(10733, "Combien de sortes de myes existe-t-il?", listOf("10", "20", "50", "100"), 2, "Nature", Difficulty.HARD, explanation = "Le terme \"mye\" désigne plusieurs espèces de mollusques bivalves marins, et on en recense environ 50 espèces différentes dans le monde."),
        Question(10734, "Quel animal peut avoir la plus grande densité de cônes dans la rétine?", listOf("l'abeille", "le mantis", "le poisson", "le perroquet"), 1, "Nature", Difficulty.HARD, explanation = "La mante religieuse possède une rétine avec une densité exceptionnelle de cônes, lui permettant une vision précise des mouvements et des couleurs."),
        Question(10735, "Quel est le plus grand dépôt de tungstène du monde?", listOf("la Chine", "le Canada", "la Russie", "le Pérou"), 0, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus grandes réserves mondiales de tungstène, concentrées principalement dans la province du Jiangxi, ce qui en fait le premier producteur et exportateur de ce métal stratégique."),
        Question(10736, "Combien de sortes de crevettes grises existe-t-il?", listOf("1", "2", "3", "5"), 1, "Nature", Difficulty.HARD, explanation = "La crevette grise se décline en deux espèces principales : la crevette grise commune (Crangon crangon) et la crevette grise des sables (Crangon allmanni)."),
        Question(10737, "Quel animal peut avoir la meilleure sensibilité à la polarisation de la lumière?", listOf("l'abeille", "le mantis", "la libellule", "le poisson"), 2, "Nature", Difficulty.HARD, explanation = "La libellule possède des photorécepteurs spécialisés dans ses yeux composés, lui permettant de détecter la lumière polarisée avec une précision inégalée, ce qui l’aide à naviguer et à chasser."),
        Question(10738, "Quel est le plus grand dépôt de molybdène du monde?", listOf("la Chine", "le Chili", "le Pérou", "la Russie"), 1, "Nature", Difficulty.HARD, explanation = "Le Chili abrite le plus grand gisement de molybdène au monde, situé dans la mine de Chuquicamata, l'une des plus grandes mines à ciel ouvert de la planète."),
        Question(10739, "Combien de sortes de crevettes Ikura existe-t-il?", listOf("1", "2", "3", "5"), 0, "Nature", Difficulty.HARD, explanation = "Ikura désigne exclusivement les œufs de saumon, et non une crevette. Il n'existe donc qu'une seule sorte d'ikura, celle issue du saumon."),
        Question(10740, "Quel animal peut avoir la meilleure capacité de discrimination de fréquences lumineuses?", listOf("le mantis", "le poisson", "l'abeille", "le perroquet"), 0, "Nature", Difficulty.HARD, explanation = "La crevette-mante possède jusqu'à 16 types de photorécepteurs, contre trois pour l'humain, lui offrant la vision la plus complexe du règne animal."),
        Question(10741, "Quel est le plus grand dépôt de vanadium du monde?", listOf("la Chine", "la Russie", "l'Afrique du Sud", "l'Australie"), 1, "Nature", Difficulty.HARD, explanation = "La Russie abrite le plus grand gisement de vanadium au monde, situé dans la région de l'Oural, avec des réserves estimées à plusieurs millions de tonnes."),
        Question(10742, "Combien de sortes de crevettes-chevrettes existe-t-il?", listOf("100", "300", "1000", "3000"), 2, "Nature", Difficulty.HARD, explanation = "Le terme \"crevette-chevette\" est un nom vernaculaire qui regroupe environ 1000 espèces différentes de crevettes d'eau douce et d'eau saumâtre, principalement de la famille des Atyidae."),
        Question(10743, "Quel animal peut avoir la plus grande capacité à percevoir les ultrasons?", listOf("la chauve-souris", "le dauphin", "le chat", "la chouette"), 1, "Nature", Difficulty.HARD, explanation = "Les dauphins utilisent l'écholocation avec des ultrasons pour naviguer et chasser, leur ouïe étant adaptée aux fréquences très élevées, bien au-delà de la portée humaine."),
        Question(10744, "Quel est le plus grand dépôt de talc du monde?", listOf("la Chine", "l'Inde", "la Russie", "le Canada"), 1, "Nature", Difficulty.HARD, explanation = "Les plus grandes réserves mondiales de talc se trouvent en Inde, notamment dans les gisements du Rajasthan."),
        Question(10745, "Combien de sortes de crevettes de roche existe-t-il?", listOf("10", "50", "200", "500"), 2, "Nature", Difficulty.HARD, explanation = "Les crevettes de roche, aussi appelées crevettes roses, comptent environ 200 espèces réparties dans les eaux tempérées et froides de l'Atlantique et de la Méditerranée."),
        Question(10746, "Quel animal peut avoir la plus grande sensibilité aux infrarouges?", listOf("le serpent à sonnettes", "le python", "la vipère", "le boa"), 3, "Nature", Difficulty.HARD, explanation = "Les boas possèdent des fossettes thermosensibles sur leur museau, leur permettant de détecter les infrarouges émis par leurs proies à distance."),
        Question(10747, "Quel est le plus grand dépôt de feldspath du monde?", listOf("la Turquie", "la Thaïlande", "la Birmanie", "la Malaisie"), 0, "Nature", Difficulty.HARD, explanation = "La Turquie possède les plus grandes réserves mondiales de feldspath, un minéral utilisé dans la céramique et le verre, avec des gisements majeurs dans les régions de l'Égée et de l'Anatolie centrale."),
        Question(10748, "Combien de sortes de crevettes pistoles existe-t-il?", listOf("50", "200", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les crevettes pistoles, aussi appelées crevettes mantis, comptent environ 500 espèces réparties dans les eaux tropicales et subtropicales."),
        Question(10749, "Quel animal peut avoir la meilleure sensibilité magnétique?", listOf("la tortue", "le pigeon", "le saumon", "la grue"), 1, "Nature", Difficulty.HARD, explanation = "Les pigeons possèdent des cristaux de magnétite dans leur bec, ce qui leur permet de détecter le champ magnétique terrestre pour s'orienter lors de leurs déplacements."),
        Question(10750, "Quel est le plus grand dépôt de bentonite du monde?", listOf("les États-Unis", "la Turquie", "la Chine", "l'Inde"), 0, "Nature", Difficulty.HARD, explanation = "Les États-Unis possèdent les plus grandes réserves de bentonite au monde, notamment dans le Wyoming, où se trouve le gisement majeur de cette argile aux propriétés absorbantes."),
        Question(10751, "Combien de sortes d'amphipodes existe-t-il?", listOf("500", "2000", "9000", "15 000"), 2, "Nature", Difficulty.HARD, explanation = "Les amphipodes, un ordre de crustacés, comptent environ 9 000 espèces décrites, principalement marines, mais aussi d'eau douce et terrestres."),
        Question(10752, "Quel animal peut avoir la meilleure sensibilité électrique?", listOf("la raie électrique", "l'anguille électrique", "le requin", "le poisson-chat"), 2, "Nature", Difficulty.HARD, explanation = "Les requins possèdent des ampoules de Lorenzini, des capteurs électriques ultra-sensibles sur leur museau, leur permettant de détecter les champs électriques infimes émis par leurs proies."),
        Question(10753, "Quel est le plus grand dépôt de kaolin du monde?", listOf("les États-Unis", "la Chine", "la Thaïlande", "l'Inde"), 1, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus vastes réserves de kaolin au monde, notamment dans la province du Jiangxi, grâce à des gisements d'argile blanche de haute qualité."),
        Question(10754, "Combien de sortes d'isopodes existe-t-il?", listOf("500", "2000", "10 000", "20 000"), 2, "Nature", Difficulty.HARD, explanation = "Les isopodes, un ordre de crustacés qui inclut les cloportes, comptent environ 10 000 espèces décrites, vivant dans des milieux marins, d'eau douce et terrestres."),
        Question(10755, "Quel animal peut avoir la meilleure sensibilité chimique?", listOf("le serpent", "l'insecte", "le poisson", "le mammifère marin"), 2, "Nature", Difficulty.HARD, explanation = "Les poissons possèdent des récepteurs chimiques extrêmement sensibles sur leur peau et leurs barbillons, leur permettant de détecter des substances à des concentrations infimes dans l'eau."),
        Question(10756, "Quel est le plus grand dépôt de perlite du monde?", listOf("les États-Unis", "la Turquie", "la Chine", "la Grèce"), 0, "Nature", Difficulty.HARD, explanation = "Les États-Unis possèdent les plus grandes réserves de perlite au monde, notamment dans l'Ouest du pays, avec des gisements majeurs au Nouveau-Mexique."),
        Question(10757, "Combien de sortes de crustacés existe-t-il?", listOf("5000", "30 000", "50 000", "100 000"), 2, "Nature", Difficulty.HARD, explanation = "Les crustacés forment un groupe très diversifié comprenant environ 50 000 espèces connues, incluant crabes, homards, crevettes et krill."),
        Question(10758, "Quel animal peut avoir la meilleure sensibilité tactile?", listOf("l'ours", "le dauphin", "l'humain", "le chat"), 1, "Nature", Difficulty.HARD, explanation = "Les dauphins possèdent des récepteurs tactiles extrêmement sensibles sur leur peau, notamment autour du museau et des nageoires, leur permettant de détecter les moindres variations de pression et de texture dans l'eau."),
        Question(10759, "Quel est le plus grand dépôt d'olivine du monde?", listOf("la Turquie", "l'Inde", "l'Australie", "l'Afrique du Sud"), 0, "Nature", Difficulty.HARD, explanation = "La Turquie abrite les plus grandes réserves mondiales d'olivine, un minéral vert utilisé dans l'industrie sidérurgique et la capture du CO2."),
        Question(10760, "Combien de sortes d'échinoïdes existe-t-il?", listOf("500", "1000", "2000", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Les échinoïdes, ou oursins, comptent environ 2000 espèces vivantes réparties dans tous les océans."),
        Question(10761, "Quel animal peut avoir la meilleure sensibilité olfactive?", listOf("le chien", "le renard", "l'ours", "le loup"), 0, "Nature", Difficulty.EASY, explanation = "Le chien possède jusqu'à 300 millions de récepteurs olfactifs, contre environ 5 millions chez l'humain, ce qui lui permet de détecter des odeurs à des concentrations infimes."),
        Question(10762, "Quel est le plus grand dépôt de calcite du monde?", listOf("la Chine", "l'Inde", "le Pakistan", "la Turquie"), 2, "Nature", Difficulty.HARD, explanation = "Les grottes de calcite les plus vastes du monde se trouvent dans les montagnes du Pakistan, notamment dans la région du Baloutchistan, où des formations géologiques uniques ont créé d'immenses dépôts cristallins."),
        Question(10763, "Combien de sortes de mollusques céphalopodes existe-t-il?", listOf("500", "1000", "1500", "2000"), 1, "Nature", Difficulty.HARD, explanation = "Les céphalopodes, comme les pieuvres et les calmars, comptent environ 1000 espèces connues, réparties dans les océans du monde."),
        Question(10764, "Quel animal peut avoir la meilleure sensibilité thermique?", listOf("le python", "le boa", "le serpent à sonnettes", "la vipère"), 0, "Nature", Difficulty.HARD, explanation = "Le python possède des fossettes thermosensibles sur ses lèvres qui détectent les infrarouges, lui permettant de localiser ses proies à sang chaud avec une précision remarquable."),
        Question(10765, "Quel est le plus grand dépôt de dolomie du monde?", listOf("la Turquie", "la Chine", "la Russie", "l'Espagne"), 3, "Nature", Difficulty.HARD, explanation = "L'Espagne abrite le plus grand gisement de dolomie au monde dans la région de Gérone, en Catalogne, où se trouve une vaste formation géologique de ce minéral carbonaté."),
        Question(10766, "Combien de sortes de tuniciers existe-t-il?", listOf("1000", "2000", "3000", "5000"), 1, "Nature", Difficulty.HARD, explanation = "Les tuniciers, comme les ascidies et les salpes, comptent environ 2000 espèces décrites dans le monde, principalement marines."),
        Question(10767, "Quel animal peut avoir la meilleure capacité d'orientation?", listOf("la tortue", "le pigeon", "la grue", "le saumon"), 1, "Nature", Difficulty.HARD, explanation = "Les pigeons possèdent un sens magnétique très développé dans leur bec, leur permettant de détecter le champ magnétique terrestre pour s'orienter avec une précision exceptionnelle sur de longues distances."),
        Question(10768, "Quel est le plus grand dépôt de fluorite du monde?", listOf("la Mongolie", "la Chine", "le Mexique", "l'Afrique du Sud"), 1, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus grandes réserves mondiales de fluorite, notamment dans la région du Hunan, où se trouve le gisement de Xianghuapu."),
        Question(10769, "Combien de sortes de cnidaires existe-t-il?", listOf("5000", "10 000", "20 000", "50 000"), 2, "Nature", Difficulty.HARD, explanation = "Les cnidaires, comme les méduses et les coraux, comptent environ 20 000 espèces recensées dans le monde. Ce nombre inclut une grande diversité de formes marines."),
        Question(10770, "Quel animal peut avoir la meilleure mémoire spatiale?", listOf("l'écureuil", "le corbeau", "l'hippocampe", "l'humain"), 1, "Nature", Difficulty.HARD, explanation = "Les corbeaux possèdent une mémoire spatiale exceptionnelle, leur permettant de se souvenir de l'emplacement de centaines de caches de nourriture sur de vastes territoires."),
        Question(10771, "Quel est le plus grand dépôt de sulfate de baryum du monde?", listOf("la Chine", "l'Inde", "les États-Unis", "le Pérou"), 0, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus grandes réserves mondiales de barytine, le minerai de sulfate de baryum, notamment dans les provinces du Hunan et du Guizhou."),
        Question(10772, "Combien de sortes de porifères existe-t-il?", listOf("1000", "5000", "8500", "15 000"), 2, "Nature", Difficulty.HARD, explanation = "Les porifères, ou éponges, comptent environ 8 500 espèces décrites dans le monde, principalement marines."),
        Question(10773, "Quel animal peut avoir la meilleure capacité d'apprentissage?", listOf("le singe", "le corbeau", "l'humain", "le dauphin"), 2, "Nature", Difficulty.MEDIUM, explanation = "L'humain possède un cortex préfrontal très développé, lui permettant une plasticité cérébrale et une capacité d'abstraction inégalées dans le règne animal."),
        Question(10774, "Quel est le plus grand dépôt de silice du monde?", listOf("la Chine", "l'Inde", "les États-Unis", "l'Australie"), 0, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus vastes réserves de silice au monde, notamment dans les provinces du Jiangsu et du Guangdong, où se trouvent d'importants gisements de quartz et de sable siliceux."),
        Question(10775, "Combien de sortes de nématodes existe-t-il?", listOf("5000", "20 000", "50 000", "100 000"), 2, "Nature", Difficulty.HARD, explanation = "Les nématodes, ou vers ronds, comptent environ 50 000 espèces décrites, mais on estime que le nombre réel pourrait atteindre plusieurs millions."),
        Question(10776, "Quel animal peut avoir la meilleure capacité de résilience?", listOf("la tardigrade", "le caméléon", "la fourmi", "le cafard"), 0, "Nature", Difficulty.HARD, explanation = "La tardigrade, aussi appelé ourson d'eau, peut survivre dans des conditions extrêmes comme le vide spatial, des températures de -272°C à 150°C, et des pressions très élevées, grâce à un état de cryptobiose."),
        Question(10777, "Quel est le plus grand dépôt de spath fluor du monde?", listOf("la Mongolie", "la Chine", "le Mexique", "l'Afrique du Sud"), 1, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus grandes réserves mondiales de spath fluor, un minéral essentiel pour la production d'acier et de fluor."),
        Question(10778, "Combien de sortes de bryozoaires existe-t-il?", listOf("100", "500", "5000", "10 000"), 2, "Nature", Difficulty.HARD, explanation = "Les bryozoaires sont de petits animaux aquatiques coloniaux. On en recense environ 5 000 espèces vivantes dans le monde."),
        Question(10779, "Quel animal peut avoir la meilleure capacité d'adaptation?", listOf("l'humain", "le cafard", "la souris", "le rat"), 1, "Nature", Difficulty.HARD, explanation = "Les blattes, ou cafards, survivent depuis plus de 300 millions d'années grâce à leur résistance aux radiations, à la famine et à leur capacité à s'adapter à presque tous les environnements."),
        Question(10780, "Quel est le plus grand dépôt d'apatite du monde?", listOf("le Maroc", "la Chine", "l'Afrique du Sud", "la Russie"), 0, "Nature", Difficulty.HARD, explanation = "Le Maroc possède les plus grandes réserves mondiales d'apatite, principalement dans la région de Khouribga, utilisée pour produire des engrais phosphatés."),
        Question(10781, "Combien de sortes de brachiopodes existe-t-il?", listOf("100", "300", "1000", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Les brachiopodes, aussi appelés \"coquilles de lampe\", comptent environ 100 espèces vivantes, mais plus de 12 000 fossiles ont été décrits. Leur diversité actuelle est faible comparée à leur abondance passée."),
        Question(10782, "Quel animal peut avoir la meilleure capacité de récupération?", listOf("le lézard", "l'étoile de mer", "l'hydre", "le vers blanc"), 2, "Nature", Difficulty.HARD, explanation = "L'hydre est capable de régénérer intégralement n'importe quelle partie de son corps coupée, ce qui lui confère une capacité de récupération quasi illimitée."),
        Question(10783, "Quel est le plus grand dépôt de phosphate du monde?", listOf("le Maroc", "la Chine", "les États-Unis", "la Russie"), 0, "Nature", Difficulty.HARD, explanation = "Le Maroc possède environ 70 % des réserves mondiales de phosphate, principalement dans la région de Khouribga, ce qui en fait le premier producteur et exportateur mondial."),
        Question(10784, "Combien de sortes de priapuliens existe-t-il?", listOf("5", "20", "100", "300"), 1, "Nature", Difficulty.HARD, explanation = "Les priapuliens, un petit embranchement de vers marins, comptent environ 20 espèces décrites à ce jour."),
        Question(10785, "Quel animal peut avoir la meilleure capacité de camouflage?", listOf("la seiche", "le caméléon", "le poisson-papillon", "le poisson-archer"), 0, "Nature", Difficulty.MEDIUM, explanation = "La seiche possède des cellules cutanées appelées chromatophores qui lui permettent de changer instantanément de couleur et de texture pour se fondre dans son environnement."),
        Question(10786, "Quel est le plus grand dépôt de potasse du monde?", listOf("la Russie", "le Canada", "l'Allemagne", "la Biélorussie"), 1, "Nature", Difficulty.HARD, explanation = "Le Canada possède les plus grandes réserves de potasse au monde, principalement situées dans la province de la Saskatchewan, où se trouvent d'immenses gisements souterrains."),
        Question(10787, "Combien de sortes de loriciféres existe-t-il?", listOf("5", "20", "100", "200"), 2, "Nature", Difficulty.HARD, explanation = "Les loricifères sont un petit embranchement d'animaux microscopiques marins découvert en 1983, et environ 100 espèces ont été décrites à ce jour."),
        Question(10788, "Quel animal peut avoir la meilleure capacité de mimétisme?", listOf("le insecte feuille", "l'insecte bâton", "le papillon citron", "la chenille verte"), 1, "Nature", Difficulty.HARD, explanation = "L'insecte bâton est un maître du camouflage, imitant parfaitement l'apparence d'une brindille pour échapper à ses prédateurs. Cette capacité de mimétisme est considérée comme l'une des plus efficaces du règne animal."),
        Question(10789, "Quel est le plus grand dépôt de sel gemme du monde?", listOf("la Pologne", "l'Allemagne", "la Chine", "le Canada"), 2, "Nature", Difficulty.HARD, explanation = "La Chine possède les plus grandes réserves de sel gemme au monde, notamment dans la région du bassin du Sichuan, où des gisements massifs sont exploités depuis des siècles."),
        Question(10790, "Combien de sortes de kinorhynques existe-t-il?", listOf("50", "200", "600", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les kinorhynques sont de petits invertébrés marins, et environ 600 espèces ont été décrites à ce jour dans le monde."),
        Question(10791, "Quel animal peut avoir la meilleure capacité de prédiction?", listOf("le corbeau", "l'humain", "le dauphin", "le singe"), 1, "Nature", Difficulty.HARD, explanation = "L'humain possède un cortex préfrontal très développé qui lui permet d'analyser des données, d'anticiper des scénarios et de faire des prédictions complexes, contrairement aux autres animaux."),
        Question(10792, "Quel est le plus grand dépôt d'améthyste du monde?", listOf("le Brésil", "l'Uruguay", "le Zambie", "la Namibie"), 0, "Nature", Difficulty.HARD, explanation = "Le Brésil abrite les plus grandes réserves d'améthyste, notamment dans l'État du Rio Grande do Sul, où des gisements comme celui d'Ametista do Sul sont exploités à grande échelle."),
        Question(10793, "Combien de sortes de cycliophores existe-t-il?", listOf("1", "5", "20", "50"), 2, "Nature", Difficulty.HARD, explanation = "Les cycliophores forment un petit embranchement animal découvert en 1995, et à ce jour, seulement 20 espèces ont été identifiées et décrites par les scientifiques."),
        Question(10794, "Quel animal peut avoir la meilleure capacité de planification?", listOf("le singe", "le corbeau", "l'éléphant", "le dauphin"), 1, "Nature", Difficulty.HARD, explanation = "Les corbeaux sont capables d'utiliser des outils et de résoudre des problèmes complexes en plusieurs étapes, comme des expériences de laboratoire l'ont démontré. Leur intelligence rivalise avec celle des grands singes dans des tests de planification."),
        Question(10795, "Quel est le plus grand dépôt de citrines du monde?", listOf("le Brésil", "l'Uruguay", "la Namibie", "Madagascar"), 0, "Nature", Difficulty.HARD, explanation = "Le Brésil, notamment dans l'État du Rio Grande do Sul, abrite les plus grandes réserves de citrines, une variété de quartz jaune."),
        Question(10796, "Combien de sortes d'acoels existe-t-il?", listOf("100", "500", "2000", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Les acoels sont des vers marins plats et simples, et environ 2000 espèces ont été décrites à ce jour, principalement dans les eaux peu profondes."),
        Question(10797, "Quel animal peut avoir la meilleure capacité de socialisation?", listOf("l'humain", "le dauphin", "le primate", "l'éléphant"), 1, "Nature", Difficulty.HARD, explanation = "Les dauphins vivent en groupes complexes appelés pods, où ils communiquent par des sifflements et des clics, et coopèrent pour chasser et protéger leurs petits. Leur cerveau développé favorise des liens sociaux forts et une capacité d'apprentissage collectif."),
        Question(10798, "Quel est le plus grand dépôt de topaze du monde?", listOf("le Brésil", "l'Afghanistan", "la Russie", "l'Australie"), 0, "Nature", Difficulty.HARD, explanation = "Le Brésil abrite les plus grandes réserves de topaze au monde, notamment dans l'État du Minas Gerais, où se trouvent des gisements majeurs comme ceux d'Ouro Preto."),
        Question(10799, "Combien de sortes de gnathostomules existe-t-il?", listOf("50", "200", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les gnathostomules, ou poissons à mâchoires, regroupent environ 500 espèces vivantes, incluant requins, raies et poissons osseux."),
        Question(10800, "Quel animal peut avoir la meilleure capacité de coopération?", listOf("la fourmi", "l'abeille", "le dauphin", "le primate"), 0, "Nature", Difficulty.HARD, explanation = "Les fourmis vivent en colonies structurées où chaque individu agit pour le bien commun, ce qui en fait des expertes de la coopération. Leur capacité à coordonner des tâches complexes comme la recherche de nourriture ou la construction de nids est inégalée dans le règne animal."),
        Question(10801, "Quel est le plus grand dépôt de rubis du monde?", listOf("la Birmanie", "la Thaïlande", "Sri Lanka", "l'Afghanistan"), 0, "Nature", Difficulty.HARD, explanation = "La Birmanie, notamment la région de Mogok, est historiquement la source la plus célèbre de rubis de haute qualité, avec des gisements exploités depuis des siècles."),
        Question(10802, "Combien de sortes de rotiféres existe-t-il?", listOf("500", "1000", "2000", "4000"), 2, "Nature", Difficulty.HARD, explanation = "Les rotifères sont de petits organismes aquatiques microscopiques, et environ 2000 espèces ont été décrites à ce jour."),
        Question(10803, "Quel animal peut avoir la meilleure capacité de leadership?", listOf("le lion", "l'éléphant", "le loup", "le dauphin"), 1, "Nature", Difficulty.HARD, explanation = "Les éléphantes matriarches guident leur troupeau grâce à leur mémoire et leur expérience, menant le groupe vers l'eau et la nourriture tout en protégeant les plus jeunes."),
        Question(10804, "Quel est le plus grand dépôt de saphirs du monde?", listOf("la Birmanie", "la Thaïlande", "Sri Lanka", "le Cachemire"), 2, "Nature", Difficulty.HARD, explanation = "Le Sri Lanka est historiquement reconnu pour ses gisements de saphirs de haute qualité, notamment dans la région de Ratnapura, surnommée la cité des pierres précieuses."),
        Question(10805, "Combien de sortes de tardigrades existe-t-il?", listOf("500", "1000", "1500", "3000"), 2, "Nature", Difficulty.HARD, explanation = "Plus de 1 500 espèces de tardigrades ont été décrites à ce jour, ces micro-organismes extrêmophiles étant présents dans divers environnements à travers le monde."),
        Question(10806, "Quel animal peut avoir la meilleure capacité de communication?", listOf("le dauphin", "l'abeille", "le corbeau", "l'humain"), 3, "Nature", Difficulty.HARD, explanation = "L'humain possède un langage articulé complexe et une capacité unique à transmettre des idées abstraites, ce qui lui confère la meilleure capacité de communication parmi tous les animaux."),
        Question(10807, "Quel est le plus grand dépôt d'émeraude du monde?", listOf("la Colombie", "la Zambie", "la Birmanie", "l'Afghanistan"), 0, "Nature", Difficulty.HARD, explanation = "La Colombie abrite les plus grandes réserves d'émeraudes au monde, notamment dans les mines de Muzo et Chivor, réputées pour leur qualité exceptionnelle."),
        Question(10808, "Combien de sortes d'archées existe-t-il?", listOf("100", "500", "1000", "5000"), 2, "Nature", Difficulty.HARD, explanation = "Les archées sont un domaine de micro-organismes unicellulaires. On en connaît environ 1 000 espèces, mais ce nombre est probablement bien plus élevé dans la nature."),
        Question(10809, "Quel animal peut avoir la meilleure capacité d'empathie?", listOf("l'humain", "le dauphin", "le primate", "l'éléphant"), 0, "Nature", Difficulty.HARD, explanation = "Les humains possèdent un cortex préfrontal très développé, leur permettant de comprendre et de partager les émotions d'autrui de manière complexe, une capacité qui dépasse celle des autres animaux."),
        Question(10810, "Quel est le plus grand dépôt de diamants du monde?", listOf("l'Afrique du Sud", "la Russie", "le Botswana", "la Namibie"), 1, "Nature", Difficulty.HARD, explanation = "La Russie abrite le plus grand gisement de diamants au monde, le champ de Kimberlite de Mirny, qui a produit des diamants de haute qualité depuis les années 1950."),
        Question(10811, "Combien de sortes de bactéries halophiles existe-t-il?", listOf("100", "500", "1000", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Les bactéries halophiles, qui prospèrent dans les milieux très salés, comptent environ 1 000 espèces connues, réparties principalement dans l'ordre des Halobacteriales."),
        Question(10812, "Quel animal peut avoir la meilleure capacité de mémoire à long terme?", listOf("l'humain", "l'éléphant", "le dauphin", "le corbeau"), 1, "Nature", Difficulty.HARD, explanation = "Les éléphants possèdent le plus gros cerveau parmi les animaux terrestres et une mémoire exceptionnelle, leur permettant de se souvenir de routes migratoires et de membres de leur groupe pendant des décennies."),
        Question(10813, "Quel est le plus grand dépôt de corindons du monde?", listOf("la Birmanie", "la Thaïlande", "Sri Lanka", "le Cambodge"), 3, "Nature", Difficulty.HARD, explanation = "Le Cambodge abrite les plus vastes gisements de corindon, notamment de rubis et de saphirs, dans la région de Pailin et de Samlot."),
        Question(10814, "Combien de sortes de méthanogènes existe-t-il?", listOf("50", "200", "500", "1000"), 2, "Nature", Difficulty.HARD, explanation = "Les méthanogènes sont des micro-organismes archées qui produisent du méthane. On en recense environ 500 espèces différentes à ce jour."),
        Question(10815, "Quel animal peut avoir la meilleure capacité d'imagination?", listOf("l'humain", "le corbeau", "le dauphin", "le primate"), 0, "Nature", Difficulty.HARD, explanation = "L'humain possède le néocortex le plus développé, lui permettant de créer des scénarios mentaux complexes et de simuler des réalités alternatives. Aucun autre animal n'a démontré une capacité d'abstraction et d'imagination aussi élaborée."),
        Question(10816, "Quel est le plus grand dépôt de béryl du monde?", listOf("les États-Unis", "la Russie", "le Brésil", "l'Afrique du Sud"), 0, "Nature", Difficulty.HARD, explanation = "Les États-Unis abritent la plus grande mine de béryl du monde, située à Spruce Pine, en Caroline du Nord. Ce gisement fournit du béryl de haute qualité, utilisé notamment pour la production de béryllium."),
        Question(10817, "Combien de sortes de thermophiles existe-t-il?", listOf("100", "500", "1000", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Les thermophiles sont des micro-organismes qui prospèrent à des températures élevées, et environ 1000 espèces différentes ont été identifiées à ce jour."),
        Question(10818, "Quel animal peut avoir la meilleure capacité d'innovation?", listOf("l'humain", "le corbeau", "l'éléphant", "le dauphin"), 0, "Nature", Difficulty.HARD, explanation = "L'humain possède un cortex préfrontal très développé, lui permettant une pensée abstraite et une résolution de problèmes complexes, ce qui lui confère la meilleure capacité d'innovation parmi les animaux."),
        Question(10819, "Quel est le plus grand dépôt de spinelle du monde?", listOf("la Birmanie", "la Thaïlande", "la Tanzanie", "Sri Lanka"), 0, "Nature", Difficulty.HARD, explanation = "La Birmanie abrite les mines de spinelle les plus célèbres, notamment dans la région de Mogok, réputée pour ses cristaux de grande qualité et de taille exceptionnelle."),
        Question(10820, "Combien de sortes de piezophiles existe-t-il?", listOf("10", "50", "200", "500"), 2, "Nature", Difficulty.HARD, explanation = "Les piezophiles sont des micro-organismes qui vivent dans les grandes profondeurs océaniques sous haute pression, et environ 200 espèces différentes ont été identifiées à ce jour."),
        Question(10821, "Quel animal peut avoir la meilleure capacité de créativité?", listOf("l'humain", "le corbeau", "le dauphin", "le primate"), 0, "Nature", Difficulty.HARD, explanation = "L'humain possède un cortex préfrontal très développé, lui permettant une pensée abstraite et une imagination créative inégalée dans le règne animal."),
        Question(10822, "Quel est le plus grand dépôt de turquoise du monde?", listOf("les États-Unis", "l'Iran", "le Chili", "l'Australie"), 0, "Nature", Difficulty.HARD, explanation = "Les États-Unis, notamment l'Arizona et le Nevada, abritent les plus grands gisements de turquoise exploités au monde."),
        Question(10823, "Combien de sortes de microbes extremophiles existe-t-il?", listOf("100", "500", "1000", "5000"), 2, "Nature", Difficulty.HARD, explanation = "On estime qu'il existe environ un millier d'espèces de microbes extrémophiles connues, capables de survivre dans des conditions extrêmes comme les hautes températures ou l'acidité."),
        Question(10824, "Quel animal peut avoir la meilleure capacité de résolution de problèmes?", listOf("l'humain", "le corbeau", "le dauphin", "le primate"), 0, "Nature", Difficulty.HARD, explanation = "L'humain possède un cortex préfrontal très développé, lui permettant l'abstraction, la planification et le raisonnement logique, des capacités cognitives supérieures à celles de tout autre animal pour résoudre des problèmes complexes."),
        Question(10825, "Quel est le plus grand dépôt de jade du monde?", listOf("la Birmanie", "la Chine", "le Népal", "la Nouvelle-Zélande"), 0, "Nature", Difficulty.HARD, explanation = "La Birmanie (Myanmar) possède les plus vastes gisements de jade au monde, situés dans la région de Hpakant, fournissant environ 70% de la production mondiale."),
        Question(10826, "Combien de sortes de plancton animal existe-t-il?", listOf("1000", "5000", "10 000", "50 000"), 2, "Nature", Difficulty.HARD, explanation = "Le zooplancton regroupe une immense diversité d'organismes marins, avec environ 10 000 espèces recensées, allant des larves de poissons aux petits crustacés."),
        Question(10827, "Quel animal peut avoir la meilleure conscience de soi?", listOf("l'humain", "le dauphin", "l'éléphant", "le primate"), 0, "Nature", Difficulty.HARD, explanation = "L'humain possède un cortex préfrontal très développé, lui permettant une introspection et une reconnaissance de soi dans un miroir dès 18 mois, un niveau inégalé dans le règne animal."),
        Question(10828, "Quel est le plus grand dépôt de lapis-lazuli du monde?", listOf("l'Afghanistan", "le Chili", "la Russie", "le Cachemire"), 0, "Nature", Difficulty.HARD, explanation = "Le lapis-lazuli le plus réputé provient des mines de la province de Badakhshan en Afghanistan, exploitées depuis plus de 6 000 ans."),
        Question(10829, "Combien de sortes de zooplancton existe-t-il?", listOf("1000", "5000", "10 000", "50 000"), 2, "Nature", Difficulty.HARD, explanation = "Le zooplancton regroupe une immense diversité d'organismes aquatiques microscopiques, avec environ 10 000 espèces recensées à ce jour."),
        Question(10830, "Quel est le plus grand herbivore vivant?", listOf("l'éléphant", "la girafe", "l'hippopotame", "le rhinocéros"), 0, "Nature", Difficulty.EASY, explanation = "L'éléphant est le plus grand animal terrestre et se nourrit exclusivement de végétaux, ce qui en fait le plus grand herbivore vivant."),
        Question(10831, "Quel est le plus grand carnivore vivant?", listOf("le lion", "le tigre", "l'ours brun", "le léopard"), 2, "Nature", Difficulty.EASY, explanation = "L'ours brun, en particulier la sous-espèce de l'ours kodiak, est le plus grand carnivore terrestre, pouvant peser jusqu'à 700 kg. Il est considéré comme le plus grand carnivore vivant sur terre."),
        Question(10832, "Quel est le plus grand omnivore vivant?", listOf("l'hippopotame", "l'ours brun", "le rhinocéros", "le porc-épic"), 1, "Nature", Difficulty.MEDIUM, explanation = "L'ours brun est considéré comme le plus grand omnivore terrestre, pouvant peser jusqu'à 700 kg et se nourrissant aussi bien de plantes que de poissons ou de mammifères."),
        Question(10833, "Quel est le plus grand insectivore terrestre vivant?", listOf("l'oryctérope", "le pangolin", "la taupe géante", "le fourmilier"), 3, "Nature", Difficulty.HARD, explanation = "Le fourmilier géant, pouvant mesurer jusqu'à 2,2 mètres de long, se nourrit exclusivement de fourmis et de termites, ce qui en fait le plus grand mammifère insectivore terrestre."),
        Question(10834, "Quel est le plus grand planctivore vivant?", listOf("la baleine bleue", "la baleine à fanons", "le requin-baleine", "la raie manta"), 2, "Nature", Difficulty.HARD, explanation = "Le requin-baleine, pouvant atteindre 18 mètres, se nourrit principalement de plancton qu'il filtre grâce à ses branchies, ce qui en fait le plus grand poisson planctivore au monde."),
        Question(10835, "Quel est le plus grand frugivore vivant?", listOf("le singe", "la chauve-souris", "l'ours", "le perroquet"), 1, "Nature", Difficulty.MEDIUM, explanation = "La chauve-souris frugivore, notamment la roussette, peut atteindre une envergure de près de deux mètres, ce qui en fait le plus grand mammifère se nourrissant exclusivement de fruits."),
        Question(10836, "Quel est le plus grand granivore vivant?", listOf("l'autruche", "l'émeu", "la grue", "l'oie"), 0, "Nature", Difficulty.HARD, explanation = "L'autruche, bien qu'oiseau, est le plus grand animal vivant se nourrissant principalement de graines, pouvant atteindre 2,7 mètres de haut."),
        Question(10837, "Quel est le plus grand néctarivore vivant?", listOf("le colibri", "la chauve-souris", "l'abeille", "le papillon"), 1, "Nature", Difficulty.HARD, explanation = "La chauve-souris, notamment la roussette, est le plus grand mammifère se nourrissant exclusivement de nectar, pouvant atteindre 40 cm d'envergure."),
        Question(10838, "Quel est le plus grand saprophage vivant?", listOf("le vautour", "le hyène", "le poisson-chat", "l'insecte"), 1, "Nature", Difficulty.HARD, explanation = "La hyène est le plus grand mammifère spécialisé dans le charognage, se nourrissant principalement de carcasses d'animaux morts."),
        Question(10839, "Quel est le plus grand parasitaire vivant?", listOf("la sangsue", "le ver", "le moustique", "le pou"), 1, "Nature", Difficulty.HARD, explanation = "Le ver solitaire (ténia) est l'un des plus grands parasites vivants, pouvant atteindre plusieurs mètres dans l'intestin humain. Il se nourrit aux dépens de son hôte."),
        Question(10840, "Quel est le plus grand détritivore vivant?", listOf("le ver de terre", "le cafard", "le poisson-chat", "le crabe"), 3, "Nature", Difficulty.HARD, explanation = "Le crabe de cocotier, ou birgus latro, est le plus grand arthropode terrestre et se nourrit principalement de matières organiques en décomposition, ce qui en fait le plus grand détritivore vivant."),
        Question(10841, "Combien de pourcentage d'oxygène y a-t-il dans l'atmosphère?", listOf("10%", "21%", "35%", "50%"), 1, "Nature", Difficulty.MEDIUM, explanation = "L'oxygène représente environ 21 % de l'atmosphère terrestre, un taux stable qui permet la respiration des êtres vivants. Ce gaz est produit principalement par la photosynthèse des plantes."),
        Question(10842, "Combien de pourcentage de dioxyde de carbone y a-t-il dans l'atmosphère?", listOf("0.04%", "1%", "5%", "10%"), 0, "Nature", Difficulty.HARD, explanation = "Le dioxyde de carbone ne représente que 0,04 % de l'atmosphère terrestre, mais ce gaz à effet de serre joue un rôle clé dans le réchauffement climatique malgré sa faible concentration."),
        Question(10843, "Quel est le gaz le plus abondant dans l'atmosphère?", listOf("l'oxygène", "le dioxyde de carbone", "l'azote", "l'argon"), 2, "Nature", Difficulty.MEDIUM, explanation = "L'azote représente environ 78% de l'atmosphère terrestre, loin devant l'oxygène (21%). Il est essentiel à la vie mais inerte pour la respiration humaine."),
        Question(10844, "Quel est le gaz à effet de serre le plus abondant?", listOf("le CO2", "le méthane", "la vapeur d'eau", "l'oxyde nitreux"), 2, "Nature", Difficulty.MEDIUM, explanation = "La vapeur d'eau est le gaz à effet de serre le plus abondant dans l'atmosphère, représentant environ 60 à 70% de l'effet de serre naturel."),
        Question(10845, "Combien de couches a l'atmosphère?", listOf("2", "3", "5", "7"), 2, "Nature", Difficulty.MEDIUM, explanation = "L'atmosphère terrestre est divisée en cinq couches principales : troposphère, stratosphère, mésosphère, thermosphère et exosphère."),
        Question(10846, "Quel est le plus haut sommet du monde sous-marin?", listOf("le Mont Tamu", "le Mont Hess", "le Mont Lomonosov", "le pic Lomonosov"), 0, "Nature", Difficulty.HARD, explanation = "Le mont Tamu, situé dans l'océan Pacifique, est un volcan sous-marin culminant à environ 4 460 mètres sous la surface, ce qui en fait le plus haut sommet sous-marin connu."),
        Question(10847, "Quel est le plus froid biome du monde?", listOf("la toundra", "la région polaire", "les hautes montagnes", "le désert arctique"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les régions polaires, comme l'Antarctique et l'Arctique, enregistrent les températures les plus basses sur Terre, atteignant souvent -50°C ou moins en hiver."),
        Question(10848, "Quel est le plus sec biome du monde?", listOf("le désert", "la toundra", "la savane", "le plateau"), 0, "Nature", Difficulty.EASY, explanation = "Le désert d'Atacama au Chili est considéré comme le plus sec, avec des zones n'ayant reçu aucune pluie depuis des siècles."),
        Question(10849, "Quel est le plus humide biome du monde?", listOf("la forêt tropicale humide", "la forêt tempérée", "les zones côtières", "les zones de marais"), 0, "Nature", Difficulty.EASY, explanation = "Les forêts tropicales humides reçoivent plus de 2000 mm de précipitations par an et ont un taux d'humidité élevé constant, ce qui en fait le biome le plus humide."),
        Question(10850, "Combien de couches océaniques principales existe-t-il?", listOf("2", "3", "5", "7"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les océans sont divisés en cinq couches principales : épipélagique, mésopélagique, bathypélagique, abyssopélagique et hadopélagique, classées selon la profondeur et la lumière."),
        Question(10851, "Quel est le plus chaud biome océanique?", listOf("le récif de corail", "la zone tropicale", "la zone équatoriale", "la zone de monsson"), 1, "Nature", Difficulty.HARD, explanation = "Les eaux océaniques tropicales reçoivent le plus fort ensoleillement annuel, ce qui élève leur température en surface au-dessus de 20°C. C'est le biome marin le plus chaud."),
        Question(10852, "Quel est le plus froid biome océanique?", listOf("la zone polaire", "la zone de transition", "la zone abyssale", "la zone bathyale"), 2, "Nature", Difficulty.HARD, explanation = "La zone abyssale, située entre 2000 et 6000 mètres de profondeur, est le biome océanique le plus froid avec des températures proches de 0°C, car la lumière solaire n'y pénètre pas."),
        Question(10853, "Combien de sortes de biomes terrestres principaux existe-t-il?", listOf("5", "8", "12", "15"), 2, "Nature", Difficulty.MEDIUM, explanation = "La classification la plus courante des biomes terrestres, basée sur le climat et la végétation, en distingue douze, incluant par exemple la forêt tropicale, la toundra et le désert."),
        Question(10854, "Combien de sortes de biomes aquatiques principaux existe-t-il?", listOf("2", "3", "5", "7"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les cinq biomes aquatiques principaux sont les océans, les récifs coralliens, les estuaires, les lacs et les rivières."),
        Question(10855, "Quel est le plus grand biome du monde?", listOf("l'océan", "la forêt tropicale", "la taïga", "la savane"), 0, "Nature", Difficulty.HARD, explanation = "L'océan recouvre environ 71% de la surface terrestre et constitue un biome continu, ce qui en fait le plus vaste écosystème de la planète."),
        Question(10856, "Quel est le deuxième plus grand biome du monde?", listOf("la forêt tropicale", "la savane", "la taïga", "la prairie"), 2, "Nature", Difficulty.HARD, explanation = "La taïga, aussi appelée forêt boréale, s'étend sur de vastes régions d'Europe, d'Asie et d'Amérique du Nord, juste après la toundra en termes de superficie."),
        Question(10857, "Quel est le troisième plus grand biome du monde?", listOf("la forêt tempérée", "la savane", "la taïga", "le désert"), 2, "Nature", Difficulty.HARD, explanation = "La taïga, aussi appelée forêt boréale, s'étend sur de vastes régions d'Europe, d'Asie et d'Amérique du Nord, ce qui en fait le troisième plus grand biome après la toundra et la forêt tropicale humide."),
        Question(10858, "Quel est le plus grand écosystème forestier du monde?", listOf("la forêt amazonienne", "la taïga", "la forêt équatoriale d'Afrique", "la forêt boréale"), 0, "Nature", Difficulty.EASY, explanation = "La forêt amazonienne s'étend sur environ 5,5 millions de kilomètres carrés, couvrant neuf pays d'Amérique du Sud, ce qui en fait la plus vaste forêt tropicale et le plus grand écosystème forestier de la planète."),
        Question(10859, "Quel est le plus grand écosystème grassland du monde?", listOf("la savane africaine", "les steppes asiatiques", "les prairies nord-américaines", "les pampas sud-américaines"), 0, "Nature", Difficulty.HARD, explanation = "La savane africaine est le plus grand écosystème de prairie (grassland) du monde, s'étendant sur environ 13 millions de kilomètres carrés à travers l'Afrique subsaharienne."),
        Question(10860, "Quel est le plus grand écosystème aquatique du monde?", listOf("l'océan Pacifique", "l'océan Atlantique", "l'océan Indien", "l'océan Arctique"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'océan Pacifique est le plus vaste et le plus profond des océans, couvrant environ un tiers de la surface terrestre, ce qui en fait le plus grand écosystème aquatique du monde."),
        Question(10861, "Quel est le plus grand récif de corail du monde?", listOf("la Grande Barrière de Corail", "le système de récifs de Belize", "le récif de Caraïbes", "le récif du Pacifique"), 0, "Nature", Difficulty.EASY, explanation = "La Grande Barrière de Corail, située au large de l'Australie, s'étend sur plus de 2300 kilomètres et est visible depuis l'espace, ce qui en fait la plus vaste structure vivante du globe."),
        Question(10862, "Quel est le plus grand lac d'eau douce du monde?", listOf("le lac Baïkal", "le lac Supérieur", "le lac Victoria", "le lac Tanganyika"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le lac Supérieur, situé entre les États-Unis et le Canada, est le plus grand lac d'eau douce du monde par sa superficie, avec environ 82 100 km². Il fait partie des Grands Lacs d'Amérique du Nord."),
        Question(10863, "Quel est le plus grand marécage du monde?", listOf("le Pantanal", "les Everglades", "le Haut-Paraná", "le delta du Mékong"), 0, "Nature", Difficulty.HARD, explanation = "Le Pantanal, situé principalement au Brésil, s'étend sur environ 150 000 km², ce qui en fait la plus vaste zone humide de la planète."),
        Question(10864, "Quel est le plus grand delta fluvial du monde?", listOf("le delta du Mékong", "le delta de l'Amazone", "le delta du Mississipi", "le delta du Nil"), 0, "Nature", Difficulty.HARD, explanation = "Le delta du Mékong, au Vietnam, est le plus grand delta fluvial du monde en termes de superficie, avec environ 40 000 km². Il est formé par les sédiments du fleuve Mékong, qui traverse six pays avant de se jeter dans la mer de Chine méridionale."),
        Question(10865, "Quel est le plus grand estuaire du monde?", listOf("l'estuaire de la Gironde", "l'estuaire du Gange", "l'estuaire de l'Amazone", "l'estuaire du Mississipi"), 2, "Nature", Difficulty.HARD, explanation = "L'estuaire de l'Amazone s'étend sur plus de 330 kilomètres de largeur à son embouchure, drainant le plus grand débit d'eau au monde."),
        Question(10866, "Quel est le plus grand système de cavernes du monde?", listOf("Mammoth Cave", "Carlsbad Caverns", "Son Doong", "Batu Caves"), 0, "Nature", Difficulty.MEDIUM, explanation = "Mammoth Cave, située dans le Kentucky, aux États-Unis, est le plus long réseau de grottes connu au monde, avec plus de 650 kilomètres de passages cartographiés."),
        Question(10867, "Quel est le plus grand canyon du monde?", listOf("le Grand Canyon", "le canyon de Zhangjiajie", "le canyon du Vézère", "le canyon du Copperbelt"), 0, "Nature", Difficulty.EASY, explanation = "Le Grand Canyon, situé dans l'Arizona aux États-Unis, est souvent considéré comme le plus grand canyon du monde en raison de sa taille impressionnante, de sa profondeur et de sa longueur, bien que d'autres canyons comme le Yarlung Tsangpo soient plus profonds."),
        Question(10868, "Quel est le plus grand gouffre du monde?", listOf("le gouffre Berger", "la grotte de Son Doong", "le gouffre Jean-Bernard", "le gouffre de Krubera"), 3, "Nature", Difficulty.HARD, explanation = "Le gouffre de Krubera, en Géorgie, est le plus profond du monde avec 2 197 mètres de profondeur explorée, surpassant tous les autres gouffres connus."),
        Question(10869, "Quel est le plus grand erg du monde?", listOf("l'Arabie", "la Grande Erg Orientale", "le Rub' al Khali", "le Nefud"), 2, "Nature", Difficulty.HARD, explanation = "Le Rub' al Khali, ou \"Quart Vide\", est le plus grand désert de sable continu au monde, s'étendant sur environ 650 000 km² dans la péninsule arabique."),
        Question(10870, "Quel est le plus grand piedmont du monde?", listOf("les piémonts du Caucase", "les piémonts de l'Himalaya", "les piémonts des Andes", "les piémonts de l'Atlas"), 1, "Nature", Difficulty.HARD, explanation = "Le piémont himalayen, s'étendant sur plus de 2 400 km, est le plus vaste au monde en raison de la collision entre les plaques indienne et eurasienne."),
        Question(10871, "Quel est le plus grand plateau du monde?", listOf("le plateau du Tibet", "le plateau de Colombie", "le plateau des Grands Lacs", "le plateau du Deccan"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le plateau du Tibet, aussi appelé toit du monde, est le plus vaste et le plus haut plateau de la planète, avec une altitude moyenne de 4 500 mètres."),
        Question(10872, "Quel est le plus grand bassin intérieur du monde?", listOf("le bassin du Tarim", "le bassin de Kalahari", "le bassin de Gobi", "le bassin de l'Amazone"), 0, "Nature", Difficulty.HARD, explanation = "Le bassin du Tarim, situé dans la région autonome ouïghoure du Xinjiang en Chine, est le plus grand bassin endoréique du monde, car il n'a aucun écoulement vers l'océan."),
        Question(10873, "Quel est le plus grand delta intérieur du monde?", listOf("le Deltaïque du Niger", "le delta intérieur du Niger", "le delta du Zaire", "le delta du Mékong"), 1, "Nature", Difficulty.HARD, explanation = "Le delta intérieur du Niger, situé au Mali, est le plus grand delta intérieur du monde car il se forme à l'intérieur des terres, loin de la mer, par l'étalement du fleuve Niger dans une vaste plaine inondable."),
        Question(10874, "Quel est le plus grand archipel du monde?", listOf("l'Indonésie", "les Philippines", "le Japon", "l'Islande"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'Indonésie est le plus grand archipel du monde avec plus de 17 000 îles, s'étendant sur l'océan Indien et Pacifique."),
        Question(10875, "Quel est le plus grand lac de montagne du monde?", listOf("le lac Titicaca", "le lac Issyk-Kol", "le lac Altai", "le lac Khosvogol"), 0, "Nature", Difficulty.HARD, explanation = "Le lac Titicaca, situé à 3 812 mètres d'altitude entre le Pérou et la Bolivie, est le plus haut lac navigable du monde et le plus grand lac de montagne par sa superficie."),
        Question(10876, "Quel est le plus grand lac glaciaire du monde?", listOf("le lac Supérieur", "le lac Baïkal", "le lac Tanganyika", "le lac Victoria"), 0, "Nature", Difficulty.HARD, explanation = "Le lac Supérieur est le plus grand lac d'eau douce du monde par sa superficie, et il s'est formé par l'érosion glaciaire lors de la dernière période glaciaire."),
        Question(10877, "Quel est le plus grand lac salé du monde?", listOf("la mer Caspienne", "la Mer Morte", "la mer d'Aral", "la Mer Noire"), 0, "Nature", Difficulty.MEDIUM, explanation = "La mer Caspienne, bien que nommée mer, est un lac salé endoréique situé entre l'Europe et l'Asie, ce qui en fait le plus grand lac salé du monde par sa superficie."),
        Question(10878, "Quel est le plus grand bassin océanique du monde?", listOf("le bassin du Pacifique", "le bassin Atlantique", "le bassin Indien", "le bassin Arctique"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le bassin du Pacifique est le plus grand bassin océanique car l'océan Pacifique couvre environ un tiers de la surface terrestre, avec une superficie de 165 millions de km²."),
        Question(10879, "Quel est le plus grand plateau océanique du monde?", listOf("le plateau des Mascareignes", "le plateau du Chagos", "le plateau de Cocos", "le plateau du Sargasso"), 0, "Nature", Difficulty.HARD, explanation = "Le plateau des Mascareignes, situé dans l'océan Indien, s'étend sur environ 2 000 km de long et 700 km de large, ce qui en fait le plus vaste plateau océanique du monde."),
        Question(10880, "Quel est le plus grand seamount du monde?", listOf("le Lomonosov", "le Tamu", "le Hess", "le Shatsky"), 0, "Nature", Difficulty.HARD, explanation = "Le Lomonosov est une chaîne de montagnes sous-marines située dans l'océan Arctique, s'étendant sur environ 1 800 km de long."),
        Question(10881, "Quel est le plus grand talus continental du monde?", listOf("le talus de Californie", "le talus du Bengale", "le talus de Nazca", "le talus de Challenger"), 1, "Nature", Difficulty.HARD, explanation = "Le talus du Bengale, au large du Bangladesh, est le plus grand du monde en raison des énormes apports sédimentaires du Gange et du Brahmapoutre."),
        Question(10882, "Quel est le plus grand trench du monde?", listOf("la fosse des Mariannes", "la fosse de Tonga", "la fosse de Kuril", "la fosse Mindanao"), 0, "Nature", Difficulty.EASY, explanation = "La fosse des Mariannes, située dans l'océan Pacifique, atteint une profondeur maximale d'environ 11 034 mètres dans le Challenger Deep, ce qui en fait le point le plus profond connu de la croûte terrestre."),
        Question(10883, "Quel est le plus grand canyon sous-marin du monde?", listOf("le canyon du Bengale", "le canyon de Monterey", "le canyon du Congo", "le canyon du Zaire"), 1, "Nature", Difficulty.HARD, explanation = "Le canyon de Monterey, situé au large de la Californie, est le plus grand canyon sous-marin connu, avec une profondeur atteignant environ 3 600 mètres et une longueur de plus de 470 kilomètres."),
        Question(10884, "Quel est le plus grand ridge du monde?", listOf("la dorsale médio-océanique", "la chaîne des Mariannes", "la chaîne du Pacifique", "la chaîne de l'Atlantique"), 0, "Nature", Difficulty.MEDIUM, explanation = "La dorsale médio-océanique est une chaîne de montagnes sous-marine qui s'étend sur environ 65 000 kilomètres à travers tous les océans, ce qui en fait la plus grande structure géologique de la planète."),
        Question(10885, "Quel est le plus grand hotspot du monde?", listOf("Hawaï", "l'Islande", "Yellowstone", "les Galápagos"), 1, "Nature", Difficulty.HARD, explanation = "L'Islande est le plus grand hotspot terrestre, situé sur la dorsale médio-atlantique, où l'activité volcanique intense est due à un panache mantellique."),
        Question(10886, "Quel est le plus grand point chaud du monde?", listOf("Hawaï", "l'Islande", "Yellowstone", "les Galápagos"), 0, "Nature", Difficulty.HARD, explanation = "Le point chaud d'Hawaï est considéré comme le plus grand du monde en volume de magma produit, ayant formé l'archipel hawaïen sur des millions d'années."),
        Question(10887, "Quel est le plus grand système de failles du monde?", listOf("la faille de San Andrés", "la faille du Rift", "la faille d'Anatolie", "la faille d'Alpine"), 1, "Nature", Difficulty.HARD, explanation = "Le système de failles du Rift est-africain s'étend sur plus de 6 000 kilomètres, de la mer Rouge au Mozambique, ce qui en fait le plus grand réseau de failles actives de la planète."),
        Question(10888, "Quel est le plus grand rift du monde?", listOf("le Rift Est-Africain", "le Rift du Rhin", "le Rift du Baïkal", "le Rift de la Mer Morte"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le Rift Est-Africain s'étend sur plus de 6 000 kilomètres, de la mer Rouge au Mozambique, résultant de la séparation des plaques tectoniques somalienne et nubienne."),
        Question(10889, "Quel est le plus grand graben du monde?", listOf("la Vallée du Jourdain", "la Vallée de la Mort", "la Vallée du Rift", "la Vallée de Baikal"), 2, "Nature", Difficulty.HARD, explanation = "La Vallée du Rift est un graben, une dépression tectonique allongée, formée par l'écartement des plaques africaine et arabique, ce qui en fait le plus grand du monde."),
        Question(10890, "Quel est le plus grand horst du monde?", listOf("le plateau de la Mésopotamie", "le plateau de l'Éthiopie", "le plateau de l'Asie de l'Est", "le plateau du Tibet"), 0, "Nature", Difficulty.HARD, explanation = "Le plateau de la Mésopotamie est considéré comme le plus grand horst du monde, une structure géologique soulevée entre deux failles."),
        Question(10891, "Quel est le plus grand bloc de croûte continentale du monde?", listOf("l'Asie", "l'Afrique", "l'Amérique du Nord", "l'Amérique du Sud"), 0, "Nature", Difficulty.HARD, explanation = "L'Asie est le plus grand continent en superficie, ce qui en fait le plus grand bloc de croûte continentale, suivi par l'Afrique."),
        Question(10892, "Quel est le plus grand bloc de croûte océanique du monde?", listOf("le Pacifique", "l'Atlantique", "l'Indien", "l'Arctique"), 0, "Nature", Difficulty.MEDIUM, explanation = "La plaque pacifique est la plus grande plaque tectonique océanique, couvrant une vaste zone de la croûte terrestre sous l'océan Pacifique."),
        Question(10893, "Quel est le plus grand champ géothermique du monde?", listOf("Yellowstone", "la Vallée de la Mort", "les Geysers", "Beppu"), 2, "Nature", Difficulty.HARD, explanation = "Les Geysers, situés en Californie, sont le plus grand champ géothermique du monde en termes de production d'électricité, exploitant la chaleur souterraine depuis 1960."),
        Question(10894, "Quel est le plus grand champ volcanique du monde?", listOf("le champ volcanique de Yellowstone", "le champ volcanique de la chaîne Juan de Fuca", "le champ volcanique de Taupo", "le champ volcanique de Coeur d'Alene"), 0, "Nature", Difficulty.HARD, explanation = "Le champ volcanique de Yellowstone, situé dans le parc national américain, est le plus vaste au monde, avec une caldeira de 72 kilomètres de long."),
        Question(10895, "Quel est le plus grand volcan du monde par volume?", listOf("le Mauna Loa", "le Mauna Kea", "le Mont-Blanc", "l'Etna"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le Mauna Loa, à Hawaï, est le volcan le plus volumineux de la Terre avec environ 75 000 km³, dépassant même le Tamu Massif sous-marin."),
        Question(10896, "Quel est le plus grand volcan du monde par superficie?", listOf("le Mauna Loa", "le Mauna Kea", "le Mont-Blanc", "l'Etna"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le Mauna Loa, à Hawaï, couvre environ 5 271 km², ce qui en fait le volcan le plus étendu en superficie sur Terre."),
        Question(10897, "Quel est le plus grand volcan actif du monde?", listOf("le Sakurajima", "le Merapi", "l'Etna", "le Yasour"), 0, "Nature", Difficulty.HARD, explanation = "Le Mauna Loa, à Hawaï, est considéré comme le plus grand volcan actif du monde en volume et en superficie, tandis que le Sakurajima, au Japon, est l'un des plus actifs mais pas le plus grand."),
        Question(10898, "Quel est le plus grand volcan éteint du monde?", listOf("le Mont-Blanc", "l'Ojos del Salado", "le Chimborazo", "l'Aconcagua"), 1, "Nature", Difficulty.HARD, explanation = "L'Ojos del Salado, situé à la frontière entre le Chili et l'Argentine, est le plus haut volcan actif du monde avec 6 893 mètres, mais il est considéré comme éteint car aucune éruption n'a été observée à l'époque moderne."),
        Question(10899, "Quel est le plus grand caldeira du monde?", listOf("la caldeira de Yellowstone", "la caldeira de Taupo", "la caldeira d'Aira", "la caldeira de Tambora"), 0, "Nature", Difficulty.HARD, explanation = "La caldeira de Yellowstone, située dans le parc national de Yellowstone aux États-Unis, est la plus grande caldeira active au monde avec environ 70 km de long."),
        Question(10900, "Quel est le plus grand geyser du monde?", listOf("Old Faithful", "le Strokkur", "le Pohutu", "le Grand Geyser"), 0, "Nature", Difficulty.HARD, explanation = "Le geyser Old Faithful, situé dans le parc national de Yellowstone aux États-Unis, est célèbre pour ses éruptions régulières et prévisibles, ce qui en fait le plus connu et le plus grand geyser actif du monde."),
        Question(10901, "Quel est le plus grand lac de cratère du monde?", listOf("le lac Crater Lake", "le lac Baïkal", "le lac Tanganyika", "le lac Victoria"), 0, "Nature", Difficulty.HARD, explanation = "Crater Lake, dans l'Oregon, s'est formé dans la caldeira du Mont Mazama après son effondrement volcanique il y a environ 7 700 ans, ce qui en fait le plus grand lac de cratère du monde."),
        Question(10902, "Quel est le plus grand lac de barrage du monde?", listOf("le lac Volta", "le lac Assouan", "le lac Kariba", "le lac Nasser"), 0, "Nature", Difficulty.HARD, explanation = "Le lac Volta, au Ghana, est le plus grand lac de barrage du monde en superficie, formé par le barrage d'Akosombo sur le fleuve Volta."),
        Question(10903, "Quel est le plus grand lac artificiel du monde?", listOf("le lac Volta", "le lac Assouan", "le lac Kariba", "le lac Nasser"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le lac Volta, au Ghana, est le plus grand réservoir artificiel du monde par sa superficie, créé par le barrage d'Akosombo sur le fleuve Volta."),
        Question(10904, "Quel est le plus grand cours d'eau du monde par débit?", listOf("l'Amazone", "le Congo", "l'Orénoque", "le Mékong"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'Amazone détient le record du plus grand débit d'eau au monde, avec une moyenne de 209 000 mètres cubes par seconde, soit plus que les sept plus grands fleuves suivants réunis."),
        Question(10905, "Quel est le plus grand cours d'eau du monde par longueur?", listOf("le Nil", "l'Amazone", "le Yangzi", "le Mississippi"), 0, "Nature", Difficulty.EASY, explanation = "Le Nil mesure environ 6 650 kilomètres, ce qui en fait le plus long fleuve du monde, devant l'Amazone."),
        Question(10906, "Quel est le plus grand cours d'eau du monde par volume?", listOf("l'Amazone", "le Congo", "l'Orénoque", "le Mékong"), 0, "Nature", Difficulty.HARD, explanation = "L'Amazone détient le record du plus grand débit d'eau au monde, avec un volume moyen de 209 000 m³ par seconde, bien supérieur à celui du Nil ou du Mississippi."),
        Question(10907, "Quel est le plus grand bassin fluvial du monde?", listOf("le bassin de l'Amazone", "le bassin du Congo", "le bassin de l'Orénoque", "le bassin du Mékong"), 0, "Nature", Difficulty.HARD, explanation = "Le bassin de l'Amazone couvre environ 7 millions de km², soit près de la moitié de l'Amérique du Sud, ce qui en fait le plus vaste réseau hydrographique de la planète."),
        Question(10908, "Quel est le plus grand système fluvial du monde?", listOf("le système du Nil", "le système de l'Amazone", "le système du Yangzi", "le système du Mississippi"), 1, "Nature", Difficulty.HARD, explanation = "Le système de l'Amazone est le plus grand du monde en volume d'eau et en superficie de bassin versant, s'étendant sur environ 7 millions de km² à travers plusieurs pays d'Amérique du Sud."),
        Question(10909, "Quel est le plus long fleuve du monde?", listOf("le Nil", "l'Amazone", "le Yangzi", "le Mississippi"), 0, "Nature", Difficulty.EASY, explanation = "Le Nil, avec ses 6 650 km, est généralement reconnu comme le plus long fleuve du monde, bien que l'Amazonie lui dispute ce titre selon les critères de mesure."),
        Question(10910, "Quel est le plus large fleuve du monde?", listOf("l'Amazone", "le Congo", "l'Orénoque", "le Mékong"), 0, "Nature", Difficulty.HARD, explanation = "L'Amazone détient le record du plus grand débit d'eau au monde et de la plus vaste superficie de bassin versant, ce qui en fait le fleuve le plus large."),
        Question(10911, "Quel est le plus profond fleuve du monde?", listOf("le Congo", "l'Amazone", "le Yangzi", "le Mississippi"), 0, "Nature", Difficulty.HARD, explanation = "Avec une profondeur maximale de 220 mètres, le fleuve Congo est le plus profond du monde, dépassant largement le deuxième, le Yangtsé."),
        Question(10912, "Quel est le plus rapide fleuve du monde?", listOf("le Yangzi", "l'Amazone", "le Congo", "le Nil"), 0, "Nature", Difficulty.HARD, explanation = "Le Yangzi est considéré comme le plus rapide grand fleuve du monde en raison de son débit élevé et de son courant puissant, surtout dans ses gorges."),
        Question(10913, "Quel est le plus froid fleuve du monde?", listOf("la Léna", "l'Ob", "l'Ienisseï", "le Lena"), 0, "Nature", Difficulty.HARD, explanation = "La Léna, en Sibérie, atteint des températures extrêmement basses, descendant jusqu'à -40°C en hiver, ce qui en fait le fleuve le plus froid du monde."),
        Question(10914, "Quel est le plus chaud fleuve du monde?", listOf("le Nil", "l'Amazone", "le Mékong", "l'Orénoque"), 1, "Nature", Difficulty.HARD, explanation = "L'Amazone détient le record du plus chaud fleuve du monde en raison de son débit immense et de son parcours en zone tropicale, où les températures élevées réchauffent ses eaux tout au long de l'année."),
        Question(10915, "Quel est le plus court fleuve du monde?", listOf("la Seine", "le Rhin", "le Koura", "le Dee"), 2, "Nature", Difficulty.HARD, explanation = "Le Koura, en Turquie, ne mesure que 71 mètres de long, ce qui en fait le plus court fleuve du monde selon le Guinness World Records."),
        Question(10916, "Quel est le fleuve avec le plus grand nombre d'affluents?", listOf("l'Amazone", "le Nil", "le Yangzi", "le Mississippi"), 0, "Nature", Difficulty.HARD, explanation = "L'Amazone détient le record du plus grand nombre d'affluents, avec plus de 1 100 cours d'eau répertoriés, dont 17 dépassent 1 500 km de long."),
        Question(10917, "Quel est le fleuve avec le plus grand nombre de cascades?", listOf("le Congo", "l'Amazone", "le Yangtze", "le Rhin"), 0, "Nature", Difficulty.HARD, explanation = "Le Congo est le fleuve qui possède le plus de cascades au monde, notamment les célèbres chutes Livingstone, une série de rapides et de chutes d'eau sur environ 350 kilomètres."),
        Question(10918, "Quel est le fleuve avec le plus grand nombre de rapides?", listOf("le Congo", "le Rhin", "l'Amazone", "le Nil"), 0, "Nature", Difficulty.HARD, explanation = "Le Congo possède plus de 300 rapides et chutes d'eau sur son cours, notamment les célèbres chutes Boyoma, ce qui en fait le fleuve le plus tumultueux du monde."),
        Question(10919, "Quel est le plus grand delta fluvial du monde?", listOf("le delta du Mékong", "le delta de l'Amazone", "le delta du Mississipi", "le delta du Nil"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le delta du Mékong, au Vietnam, est le plus grand delta fluvial du monde avec une superficie d'environ 40 000 km². Il se forme par les sédiments déposés par le fleuve Mékong à son embouchure dans la mer de Chine méridionale."),
        Question(10920, "Quel est le plus grand estuaire du monde?", listOf("l'estuaire de l'Amazone", "l'estuaire du Gange", "l'estuaire du Mississipi", "l'estuaire du Nil"), 0, "Nature", Difficulty.HARD, explanation = "L'estuaire de l'Amazone s'étend sur plus de 330 kilomètres de large à son embouchure, ce qui en fait le plus vaste du monde. Il draine un bassin de 7 millions de km², le plus grand de la planète."),
        Question(10921, "Quel animal migrateur parcourt la plus grande distance?", listOf("la baleine grise", "l'anguille", "la sterne polaire", "le caribou"), 2, "Nature", Difficulty.MEDIUM, explanation = "La sterne polaire migre chaque année de l'Arctique à l'Antarctique, parcourant environ 70 000 kilomètres, soit la plus longue migration de tout le règne animal."),
        Question(10922, "Quel animal a le plus de pattes?", listOf("la mille-pattes", "la limule", "le scorpion", "l'araignée"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le mille-pattes, ou myriapode, peut avoir jusqu'à 750 pattes, bien que le nombre varie selon les espèces, ce qui en fait l'animal avec le plus de pattes connu."),
        Question(10923, "Quel est l'animal qui pond le plus d'œufs à la fois?", listOf("la morue", "la sardine", "le hareng", "l'anchois"), 0, "Nature", Difficulty.HARD, explanation = "La morue peut pondre jusqu'à 9 millions d'œufs en une seule ponte, ce qui en fait l'animal avec la plus grande fécondité ponctuelle."),
        Question(10924, "Quel est l'animal avec la plus courte durée de vie?", listOf("la mouche éphémère", "la libellule", "le papillon", "la fourmi"), 0, "Nature", Difficulty.MEDIUM, explanation = "La mouche éphémère adulte ne vit que quelques heures à quelques jours, car elle ne se nourrit pas et son unique but est de se reproduire."),
        Question(10925, "Quel est l'animal avec la plus longue durée de vie?", listOf("la tortue géante", "le perroquet", "le humain", "la baleine"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les perroquets, notamment les aras, peuvent vivre jusqu'à 80 ans en captivité, ce qui en fait l'un des animaux domestiques les plus longévifs."),
        Question(10926, "Quel est l'animal qui dort le plus?", listOf("la chauve-souris", "l'ours", "le koala", "le crocodile"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le koala dort en moyenne 20 à 22 heures par jour pour économiser l'énergie nécessaire à la digestion de son régime alimentaire pauvre en nutriments, composé principalement de feuilles d'eucalyptus."),
        Question(10927, "Quel est l'animal qui dort le moins?", listOf("le requin", "la girafe", "l'éléphant", "le chameau"), 0, "Nature", Difficulty.HARD, explanation = "Les requins doivent nager en permanence pour faire circuler l'eau oxygénée sur leurs branchies, ce qui les empêche de dormir comme les autres animaux. Certaines espèces peuvent entrer dans un état de repos partiel tout en continuant à nager."),
        Question(10928, "Quel est l'animal qui boit le plus d'eau?", listOf("la girafe", "le chameau", "l'éléphant", "l'hippopotame"), 3, "Nature", Difficulty.HARD, explanation = "L'hippopotame passe la majeure partie de son temps dans l'eau pour se protéger du soleil et réguler sa température corporelle, ce qui le conduit à boire de grandes quantités d'eau quotidiennement."),
        Question(10929, "Quel est l'animal qui boit le moins d'eau?", listOf("le chameau", "le kangourou", "le renard du désert", "la hyène"), 1, "Nature", Difficulty.HARD, explanation = "Le kangourou possède un métabolisme très efficace qui lui permet de survivre dans des environnements arides en buvant très peu, car il tire l'essentiel de son hydratation des plantes qu'il consomme."),
        Question(10930, "Quel est l'animal qui mange le plus?", listOf("l'éléphant", "la baleine", "l'hippopotame", "l'ours"), 1, "Nature", Difficulty.HARD, explanation = "La baleine bleue consomme jusqu'à 4 tonnes de krill par jour, ce qui en fait l'animal avec le plus grand appétit en termes de masse alimentaire."),
        Question(10931, "Quel est l'animal qui mange le moins?", listOf("le colibri", "le hérisson", "la souris", "la chauve-souris"), 0, "Nature", Difficulty.HARD, explanation = "Le colibri a un métabolisme extrêmement rapide et doit manger constamment pour survivre, mais il compense par des périodes de torpeur où son métabolisme ralentit fortement, lui permettant de jeûner la nuit."),
        Question(10932, "Quel est l'animal qui respire le plus?", listOf("la souris", "le pigeon", "le lapin", "l'oiseau"), 3, "Nature", Difficulty.HARD, explanation = "Les oiseaux ont un système respiratoire très efficace avec des sacs aériens qui permettent un flux d'air unidirectionnel, leur assurant un apport constant en oxygène même en vol."),
        Question(10933, "Quel est l'animal qui respire le moins?", listOf("la baleine", "le crocodile", "le requin", "la tortue"), 1, "Nature", Difficulty.HARD, explanation = "Le crocodile peut retenir sa respiration sous l'eau pendant plus d'une heure grâce à son métabolisme lent et à sa capacité à ralentir son rythme cardiaque."),
        Question(10934, "Quel est l'animal qui transpire le plus?", listOf("le cheval", "l'humain", "le chien", "le chat"), 0, "Nature", Difficulty.HARD, explanation = "Les chevaux transpirent abondamment pour réguler leur température corporelle lors d'efforts intenses, produisant jusqu'à 15 litres de sueur par heure."),
        Question(10935, "Quel est l'animal qui transpire le moins?", listOf("le chameau", "le chat", "le chien", "l'oiseau"), 0, "Nature", Difficulty.HARD, explanation = "Le chameau transpire très peu grâce à son pelage épais qui isole la chaleur et à sa capacité à réguler sa température corporelle, ce qui lui permet de conserver l'eau dans les déserts arides."),
        Question(10936, "Quel est l'animal qui saute le plus haut?", listOf("la puce", "le kangourou", "la grenouille", "la sauterelle"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le kangourou peut sauter jusqu'à 3 mètres de haut grâce à ses puissantes pattes arrière et sa queue qui sert de balancier."),
        Question(10937, "Quel est l'animal qui saute le plus loin?", listOf("la puce", "le kangourou", "la grenouille", "la sauterelle"), 0, "Nature", Difficulty.HARD, explanation = "La puce peut sauter jusqu'à 200 fois sa propre longueur, ce qui en fait l'animal le plus performant en saut proportionnellement à sa taille."),
        Question(10938, "Quel est l'animal qui plonge le plus profond?", listOf("le phoque", "la baleine", "le cachalot", "le dauphin"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le cachalot peut plonger jusqu'à 2 000 mètres de profondeur pour chasser des calmars géants, ce qui en fait le mammifère plongeant le plus profondément."),
        Question(10939, "Quel est l'animal qui nage le plus vite?", listOf("le dauphin", "le poisson-voile", "le requin-tigre", "la truite"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le poisson-voile peut atteindre 110 km/h en vitesse de pointe, ce qui en fait le nageur le plus rapide du règne animal."),
        Question(10940, "Quel est l'animal qui marche le plus longtemps sans repos?", listOf("la girafe", "le chameau", "l'autruche", "le cheval"), 1, "Nature", Difficulty.HARD, explanation = "Le chameau peut parcourir de longues distances dans le désert sans boire ni se reposer, grâce à ses réserves de graisse dans ses bosses et son métabolisme adapté."),
        Question(10941, "Quel est l'animal qui court le plus longtemps sans s'arrêter?", listOf("le loup", "l'antilope", "le chameau", "le cheval"), 2, "Nature", Difficulty.HARD, explanation = "Le chameau peut parcourir de longues distances dans le désert sans boire ni s'arrêter, grâce à ses réserves d'eau et de graisse dans ses bosses."),
        Question(10942, "Quel est l'animal qui vole le plus longtemps sans s'arrêter?", listOf("l'albatros", "l'aigle", "la cigogne", "le condor"), 0, "Nature", Difficulty.HARD, explanation = "L'albatros peut voler sans se poser pendant plusieurs semaines, voire des mois, grâce à ses longues ailes et sa technique de vol plané au-dessus des océans."),
        Question(10943, "Quel est l'animal qui allaite le plus longtemps?", listOf("la baleine", "l'éléphant", "l'ours", "le humain"), 1, "Nature", Difficulty.HARD, explanation = "L'éléphanteau peut téter jusqu'à l'âge de 3 ou 4 ans, parfois plus, ce qui constitue la plus longue période d'allaitement chez les mammifères terrestres."),
        Question(10944, "Quel est l'animal qui élève ses jeunes le plus longtemps?", listOf("l'humain", "l'éléphant", "le dauphin", "le singe"), 0, "Nature", Difficulty.HARD, explanation = "L'humain a la plus longue période de dépendance juvénile parmi tous les animaux, avec des soins parentaux qui durent souvent plus d'une décennie."),
        Question(10945, "Quel est l'animal qui a la plus grande portée?", listOf("la souris", "le porc", "la lapine", "la vache"), 1, "Nature", Difficulty.MEDIUM, explanation = "La truie peut donner naissance à une portée de 8 à 14 porcelets en moyenne, avec des records dépassant 30 petits, ce qui en fait le mammifère terrestre à la plus grande portée."),
        Question(10946, "Quel est l'animal qui a la plus petite portée?", listOf("l'éléphant", "la baleine", "la girafe", "l'hippopotame"), 0, "Nature", Difficulty.HARD, explanation = "La gestation de l'éléphante dure près de 22 mois, et elle donne généralement naissance à un seul petit, ce qui constitue la plus petite portée parmi les mammifères."),
        Question(10947, "Quel est l'animal qui se reproduit le plus rapidement?", listOf("le lapin", "la mouche", "la bactérie", "le virus"), 2, "Nature", Difficulty.HARD, explanation = "Les bactéries se reproduisent par division cellulaire toutes les 20 à 30 minutes dans des conditions idéales, ce qui dépasse largement le rythme de reproduction de tout animal."),
        Question(10948, "Quel est l'animal qui se reproduit le plus lentement?", listOf("l'éléphant", "la baleine", "la tortue", "l'humain"), 1, "Nature", Difficulty.HARD, explanation = "La baleine franche a une gestation de 12 à 14 mois et les femelles ne mettent bas qu’un seul petit tous les 3 à 5 ans, ce qui en fait le mammifère au cycle de reproduction le plus lent."),
        Question(10949, "Quel est l'animal qui meurt le plus jeune?", listOf("la mouche éphémère", "la libellule", "le moustique", "la mouche"), 0, "Nature", Difficulty.MEDIUM, explanation = "La mouche éphémère vit seulement quelques heures à quelques jours à l'état adulte, ce qui en fait l'animal à la durée de vie la plus courte."),
        Question(10950, "Quel est l'animal qui meurt le plus vieux?", listOf("la tortue géante", "le perroquet", "la baleine", "le humain"), 2, "Nature", Difficulty.HARD, explanation = "Certaines espèces de baleines, comme la baleine boréale, peuvent vivre plus de 200 ans, ce qui en fait les mammifères les plus longévifs connus."),
        Question(10951, "Quel est l'animal qui a le meilleur système immunitaire?", listOf("la chauve-souris", "le cafard", "le humain", "la méduse"), 1, "Nature", Difficulty.HARD, explanation = "Le cafard possède un système immunitaire extrêmement résistant, capable de survivre à des radiations et à des environnements hostiles grâce à des enzymes antimicrobiennes puissantes."),
        Question(10952, "Quel est l'animal qui régénère le plus rapidement?", listOf("l'étoile de mer", "le lézard", "l'hydre", "la planaire"), 2, "Nature", Difficulty.HARD, explanation = "L'hydre, un petit cnidaire d'eau douce, possède des cellules souches qui lui permettent de régénérer n'importe quelle partie de son corps en quelques jours."),
        Question(10953, "Quel est l'animal qui vieillit le plus lentement?", listOf("la tortue géante", "la baleine", "le perroquet", "le humain"), 0, "Nature", Difficulty.HARD, explanation = "Les tortues géantes ont un métabolisme extrêmement lent et une longévité exceptionnelle, pouvant dépasser 150 ans, ce qui ralentit leur processus de vieillissement."),
        Question(10954, "Quel est l'animal qui rétrécit avec l'âge?", listOf("le humain", "le chien", "le chat", "le singe"), 0, "Nature", Difficulty.HARD, explanation = "Le corps humain perd de la masse osseuse et musculaire avec l'âge, ce qui entraîne une diminution de la taille, notamment après 40 ans."),
        Question(10955, "Quel est l'animal qui gagne du poids le plus rapidement?", listOf("l'hippopotame", "l'ours", "la baleine", "l'éléphant"), 2, "Nature", Difficulty.HARD, explanation = "La baleine bleue, le plus grand animal vivant, peut prendre jusqu'à 90 kg par jour pendant l'allaitement, grâce à un lait très riche en matières grasses."),
        Question(10956, "Quel est l'animal qui perd du poids le plus rapidement?", listOf("la baleine", "l'ours", "le phoque", "le renne"), 0, "Nature", Difficulty.HARD, explanation = "Une baleine peut perdre jusqu'à 30% de son poids corporel pendant la migration, car elle jeûne sur de longues distances."),
        Question(10957, "Quel est l'animal qui change le plus de couleur?", listOf("le caméléon", "la seiche", "le lézard", "la grenouille"), 1, "Nature", Difficulty.MEDIUM, explanation = "La seiche possède des cellules cutanées appelées chromatophores qui lui permettent de modifier instantanément la couleur et la texture de sa peau pour se camoufler ou communiquer."),
        Question(10958, "Quel est l'animal qui change le plus de forme?", listOf("la méduse", "l'éponge", "le poulpe", "le poisson"), 1, "Nature", Difficulty.HARD, explanation = "Les éponges sont des animaux capables de se déformer et de se régénérer complètement, pouvant passer à travers un tamis pour reformer leur structure."),
        Question(10959, "Quel est l'animal qui change le plus de texture?", listOf("le poulpe", "la seiche", "la méduse", "l'anémone"), 0, "Nature", Difficulty.HARD, explanation = "Le poulpe peut modifier l'apparence de sa peau en changeant de couleur, de motif et même de texture grâce à des cellules spécialisées appelées chromatophores et papilles musculaires."),
        Question(10960, "Quel est l'animal qui a le plus de muscles?", listOf("l'humain", "le cheval", "l'éléphant", "la baleine"), 2, "Nature", Difficulty.HARD, explanation = "L'éléphant possède environ 150 000 muscles dans sa trompe, ce qui en fait l'animal avec le plus grand nombre de muscles."),
        Question(10961, "Quel est l'animal qui a le moins de muscles?", listOf("la méduse", "l'éponge", "la lamproie", "le ver blanc"), 1, "Nature", Difficulty.HARD, explanation = "Les éponges sont des animaux filtreurs sans tissus ni organes, et elles ne possèdent pas de muscles car elles sont composées de cellules spécialisées qui leur permettent de se contracter sans système musculaire."),
        Question(10962, "Quel est l'animal qui a le plus d'os?", listOf("le serpent", "le poisson", "l'oiseau", "l'humain"), 1, "Nature", Difficulty.HARD, explanation = "Les poissons possèdent un grand nombre d'os, notamment grâce à leurs arêtes et à leur squelette complexe, ce qui leur confère le record parmi les animaux."),
        Question(10963, "Quel est l'animal qui a le moins d'os?", listOf("la méduse", "l'éponge", "le vers", "la limace"), 0, "Nature", Difficulty.HARD, explanation = "La méduse n'a pas d'os, car elle est composée à 95 % d'eau et son corps est gélatineux, sans squelette interne ni externe."),
        Question(10964, "Quel est l'animal qui a le plus de nerfs?", listOf("le poulpe", "l'humain", "le dauphin", "le singe"), 0, "Nature", Difficulty.HARD, explanation = "Le poulpe possède un système nerveux très développé avec environ 500 millions de neurones, dont la majorité sont répartis dans ses bras, ce qui lui confère une grande capacité de contrôle et de coordination."),
        Question(10965, "Quel est l'animal qui a le moins de nerfs?", listOf("la méduse", "l'éponge", "la limace", "le vers blanc"), 1, "Nature", Difficulty.HARD, explanation = "Les éponges sont des animaux filtreurs dépourvus de système nerveux, de muscles et d'organes, ce qui en fait l'animal avec le moins de nerfs."),
        Question(10966, "Quel est l'animal qui a le plus de cheveux par centimètre carré?", listOf("la loutre", "le chat", "le chien", "le singe"), 0, "Nature", Difficulty.HARD, explanation = "La loutre possède la fourrure la plus dense du règne animal, avec jusqu'à 125 000 poils par centimètre carré, ce qui lui permet de rester au sec et isolée dans l'eau froide."),
        Question(10967, "Quel est l'animal qui a le plus d'écailles?", listOf("le poisson", "le serpent", "le pangolin", "l'armadillo"), 2, "Nature", Difficulty.HARD, explanation = "Le pangolin est le mammifère le plus couvert d'écailles, car son corps est entièrement recouvert d'écailles de kératine, ce qui le distingue de tous les autres animaux."),
        Question(10968, "Quel est l'animal qui a le plus de plumes?", listOf("l'autruche", "le cygne", "le paon", "l'aigle"), 1, "Nature", Difficulty.HARD, explanation = "Le cygne possède jusqu'à 25 000 plumes, soit le plus grand nombre connu chez un oiseau, ce qui lui permet de flotter et de se protéger du froid."),
        Question(10969, "Quel est l'animal qui a le plus de piquants?", listOf("le porc-épic", "l'oursin", "le hérisson", "l'échidné"), 1, "Nature", Difficulty.HARD, explanation = "L'oursin possède des milliers de piquants mobiles sur sa coquille calcaire, ce qui en fait l'animal le plus épineux."),
        Question(10970, "Quel est l'animal qui a le plus de défenses?", listOf("l'éléphant", "le morse", "le narval", "l'hippopotame"), 3, "Nature", Difficulty.HARD, explanation = "L'hippopotame possède de grandes canines et incisives en ivoire, utilisées pour le combat et la défense du territoire."),
        Question(10971, "Quel est l'animal qui a le plus de cornes?", listOf("la girafe", "l'antilope", "le mouton", "la chèvre"), 1, "Nature", Difficulty.HARD, explanation = "L'antilope saïga possède le plus grand nombre de cornes parmi les mammifères, avec deux paires distinctes, une caractéristique unique chez les bovidés."),
        Question(10972, "Quel est l'animal qui a le plus de bois?", listOf("l'élan", "le renne", "le cerf", "le chevreuil"), 0, "Nature", Difficulty.HARD, explanation = "L'élan possède les plus grands bois parmi les cervidés, avec une envergure pouvant atteindre deux mètres. Ces bois sont portés par les mâles et tombent chaque hiver."),
        Question(10973, "Quel est l'animal qui a les ongles les plus longs?", listOf("l'ours", "le pangolin", "le paresseux", "l'oryctérope"), 2, "Nature", Difficulty.HARD, explanation = "Les paresseux ont des griffes très longues, mesurant jusqu'à 7,5 cm, qui leur servent à s'accrocher aux branches dans la canopée des forêts tropicales."),
        Question(10974, "Quel est l'animal qui a les serres les plus puissantes?", listOf("l'aigle", "le faucon", "la chouette", "le hibou"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'aigle possède des serres capables d'exercer une pression de plusieurs centaines de kilos par centimètre carré, lui permettant de saisir et tuer des proies de grande taille."),
        Question(10975, "Quel est l'animal qui a les crocs les plus longs?", listOf("l'hippopotame", "le morse", "l'éléphant", "le sanglier"), 1, "Nature", Difficulty.HARD, explanation = "Les canines supérieures du morse peuvent atteindre jusqu'à un mètre de long chez les mâles, servant à briser la glace et à se hisser hors de l'eau."),
        Question(10976, "Quel est l'animal qui a les canines les plus pointues?", listOf("le cobra", "la vipère", "le crotale", "le mamba noir"), 2, "Nature", Difficulty.HARD, explanation = "Le crotale possède des canines creuses et extrêmement pointues, capables d'injecter du venin, ce qui en fait l'animal avec les canines les plus acérées."),
        Question(10977, "Quel est l'animal qui a les ailes les plus larges?", listOf("l'albatros", "l'aigle", "le condor", "la mouche"), 2, "Nature", Difficulty.HARD, explanation = "Le condor des Andes détient le record d'envergure parmi les oiseaux terrestres, avec des ailes pouvant atteindre 3,2 mètres."),
        Question(10978, "Quel est l'animal qui a les nageoires les plus grandes?", listOf("la raie manta", "le poisson-voile", "la baleine bleue", "le requin-baleine"), 0, "Nature", Difficulty.HARD, explanation = "La raie manta possède les plus grandes nageoires pectorales, pouvant atteindre jusqu'à 7 mètres d'envergure, ce qui lui permet de planer dans l'eau comme un oiseau."),
        Question(10979, "Quel est l'animal qui a la queue la plus longue?", listOf("le lion", "le singe hurleur", "le lézard-dragon barbu", "le rat musqué"), 1, "Nature", Difficulty.HARD, explanation = "Le singe hurleur possède une queue préhensile qui peut mesurer jusqu'à un mètre de long, soit plus que la longueur de son corps. Cette queue lui sert à s'agripper aux branches dans la canopée."),
        Question(10980, "Quel est l'animal qui a la queue la plus préhensile?", listOf("le singe", "l'opossum", "l'iguane", "le caméléon"), 0, "Nature", Difficulty.HARD, explanation = "Les singes du Nouveau Monde, comme le singe-araignée, possèdent une queue préhensile capable de saisir des branches, servant de cinquième membre pour se déplacer dans les arbres."),
        Question(10981, "Quel est l'animal qui a la langue la plus longue?", listOf("la girafe", "le lézard-dragon de Komodo", "le fourmilier", "l'autruche"), 0, "Nature", Difficulty.MEDIUM, explanation = "La girafe possède une langue pouvant atteindre 45 à 50 centimètres, ce qui lui permet de saisir les feuilles d’acacia épineuses sans se blesser."),
        Question(10982, "Quel est l'animal qui a la langue la plus préhensile?", listOf("le caméléon", "la girafe", "le fourmilier", "le koala"), 0, "Nature", Difficulty.HARD, explanation = "La langue du caméléon peut s'allonger jusqu'à deux fois la taille de son corps et est dotée d'un muscle spécial qui lui permet d'attraper des proies avec une grande précision."),
        Question(10983, "Quel est l'animal qui a les oreilles les plus longues?", listOf("le lièvre du Jackrabbit", "l'âne", "la chauve-souris", "le fennec"), 2, "Nature", Difficulty.HARD, explanation = "La chauve-souris à oreilles de souris possède des oreilles pouvant atteindre 4 centimètres, soit près d'un tiers de la longueur de son corps."),
        Question(10984, "Quel est l'animal qui a les oreilles les plus mobiles?", listOf("le chat", "le chien", "le cheval", "l'âne"), 0, "Nature", Difficulty.HARD, explanation = "Le chat possède 32 muscles dans chaque oreille, lui permettant de les orienter indépendamment à 180 degrés pour localiser précisément les sons."),
        Question(10985, "Quel est l'animal qui a le nez le plus sensible?", listOf("le chien", "le requin", "l'ours", "le loup"), 0, "Nature", Difficulty.EASY, explanation = "Le chien possède environ 300 millions de récepteurs olfactifs, contre 5 à 6 millions chez l'humain, ce qui lui confère une capacité de détection des odeurs extrêmement développée."),
        Question(10986, "Quel est l'animal qui a les naseaux les plus grands?", listOf("l'hippopotame", "l'éléphant", "la baleine", "le chameau"), 2, "Nature", Difficulty.HARD, explanation = "La baleine possède les plus grands naseaux du règne animal, appelés évents, situés sur le dessus de sa tête. Ces orifices nasaux peuvent mesurer jusqu'à 30 centimètres de large chez certaines espèces."),
        Question(10987, "Quel est l'animal qui a les pupilles les plus grandes?", listOf("la chauve-souris", "le loup", "la chouette", "le chat"), 2, "Nature", Difficulty.HARD, explanation = "La chouette a des pupilles très larges pour capter un maximum de lumière, ce qui lui permet de chasser efficacement la nuit."),
        Question(10988, "Quel est l'animal qui a les pupilles les plus petites?", listOf("l'aigle", "l'autruche", "le cheval", "le lapin"), 0, "Nature", Difficulty.HARD, explanation = "Les aigles ont des pupilles très petites par rapport à leur taille oculaire, ce qui leur permet de voir avec une acuité extrême tout en limitant l'éblouissement."),
        Question(10989, "Quel est l'animal qui a les yeux les plus rapprochés?", listOf("le poisson-globe", "l'hippocampe", "le poisson-archer", "le poisson-papillon"), 0, "Nature", Difficulty.HARD, explanation = "Le poisson-globe a les yeux très rapprochés car ils sont positionnés sur le dessus de sa tête, ce qui lui offre une vision binoculaire pour mieux viser ses proies."),
        Question(10990, "Quel est l'animal qui a les yeux les plus éloignés?", listOf("le cheval", "la gazelle", "la girafe", "l'antilope"), 0, "Nature", Difficulty.HARD, explanation = "Chez le cheval, les yeux sont placés très latéralement sur la tête, ce qui lui offre un champ de vision panoramique de près de 360 degrés."),
        Question(10991, "Quel est l'animal qui a les yeux les plus hauts?", listOf("l'hippopotame", "la girafe", "l'autruche", "le chameau"), 0, "Nature", Difficulty.HARD, explanation = "Les yeux de l'hippopotame sont placés haut sur son crâne, ce qui lui permet de voir au-dessus de l'eau tout en restant quasiment immergé."),
        Question(10992, "Quel est l'animal qui a les yeux les plus bas?", listOf("le poisson-chat", "la baudroie", "le poisson des abysses", "le poisson-globe"), 0, "Nature", Difficulty.HARD, explanation = "Le poisson-chat a des yeux situés très bas sur son corps, presque sous la tête, ce qui lui permet de fouiller le fond des eaux troubles pour trouver sa nourriture."),
        Question(10993, "Quel est l'animal qui a les yeux les plus latéraux?", listOf("le cheval", "la gazelle", "le lapin", "la girafe"), 2, "Nature", Difficulty.HARD, explanation = "Le lapin possède des yeux placés très latéralement, ce qui lui offre un champ de vision presque à 360 degrés pour détecter les prédateurs."),
        Question(10994, "Quel est l'animal qui a les yeux les plus frontaux?", listOf("le hibou", "la chouette", "l'humain", "le singe"), 3, "Nature", Difficulty.HARD, explanation = "Les singes ont des yeux frontaux car ils sont des primates arboricoles, ce qui leur offre une vision binoculaire pour mieux évaluer les distances en sautant de branche en branche."),
        Question(10995, "Quel est l'animal qui a les yeux les plus grands en proportion du corps?", listOf("le colibri", "la chouette", "la larve de libellule", "la mouche"), 1, "Nature", Difficulty.HARD, explanation = "La chouette possède des yeux très volumineux par rapport à sa taille, ce qui lui offre une excellente vision nocturne pour chasser dans l'obscurité."),
        Question(10996, "Quel est l'animal qui a les yeux les plus petits en proportion du corps?", listOf("la mouche", "l'abeille", "le moustique", "la fourmi"), 3, "Nature", Difficulty.HARD, explanation = "Les fourmis ont des yeux composés minuscules par rapport à leur taille, car elles dépendent davantage de leurs antennes et de leur odorat que de la vision pour se déplacer et communiquer."),
        Question(10997, "Quel est l'animal qui a les yeux les plus mobiles?", listOf("le caméléon", "le poisson-globe", "l'autruche", "le lézard"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le caméléon possède des yeux capables de bouger indépendamment l'un de l'autre, avec un champ de vision à 360 degrés."),
        Question(10998, "Quel est l'animal qui a les yeux les plus fixes?", listOf("le serpent", "le crocodile", "le glaçon", "le requin"), 1, "Nature", Difficulty.HARD, explanation = "Le crocodile a une vision très fixe car ses yeux sont conçus pour rester immobiles, ce qui l’aide à guetter ses proies sans trahir sa présence."),
        Question(10999, "Quel est l'animal qui peut voir le plus de directions à la fois?", listOf("le pigeon", "la chauve-souris", "le lézard", "le poisson"), 0, "Nature", Difficulty.HARD, explanation = "Le pigeon possède un champ de vision de près de 340 degrés grâce à ses yeux placés sur les côtés de la tête, lui permettant de voir dans presque toutes les directions sans bouger.")
    )
